const problems = [{"id":1,"title":"Two Sum","difficulty":"Easy","pattern":"Hash Map","trigger":"Two values must satisfy a target relationship; O(n²) pair search is too slow.","anti":"If input is sorted and only one pair is needed, two pointers can use O(1) extra space.","insight":"For x, only target - x matters, so store previously seen values.","brute":"O(n²), O(1): test every pair.","opt":"O(n) average, O(n): complement lookup.","pitfalls":"Check before inserting the current value; return indices, not values.","code":"from typing import List\n\ndef two_sum(nums: List[int], target: int) -> List[int]:\n    seen: dict[int, int] = {}\n    for i, x in enumerate(nums):\n        need = target - x\n        if need in seen:\n            return [seen[need], i]\n        seen[x] = i\n    return []"},{"id":2,"title":"Add Two Numbers","difficulty":"Medium","pattern":"Linked List","trigger":"Two numbers are represented digit-by-digit in linked lists.","anti":"Converting to integers is inappropriate for arbitrarily long lists and loses the linked-list constraint.","insight":"Add corresponding digits while carrying to the next position.","brute":"O(n), O(n) if rebuilding through a list/number.","opt":"O(max(m,n)), O(1) extra beyond output.","pitfalls":"Remember the final carry; one list may be longer.","code":"from typing import Optional\n\ndef add_two_numbers(l1, l2):\n    dummy = cur = ListNode(0)\n    carry = 0\n    while l1 or l2 or carry:\n        a = l1.val if l1 else 0\n        b = l2.val if l2 else 0\n        carry, digit = divmod(a + b + carry, 10)\n        cur.next = ListNode(digit)\n        cur = cur.next\n        l1 = l1.next if l1 else None\n        l2 = l2.next if l2 else None\n    return dummy.next"},{"id":3,"title":"Longest Substring Without Repeating Characters","difficulty":"Medium","pattern":"Sliding Window","trigger":"Contiguous substring + longest + uniqueness/frequency constraint.","anti":"If the problem is subsequence rather than substring, a sliding window is not automatically appropriate.","insight":"Maintain the smallest left boundary that keeps the current window valid.","brute":"O(n²), O(k): enumerate substrings and test uniqueness.","opt":"O(n), O(k): sliding window with last-seen indices.","pitfalls":"Only move left forward; do not move it backward after seeing an old character.","code":"def length_of_longest_substring(s: str) -> int:\n    left = ans = 0\n    last: dict[str, int] = {}\n    for right, ch in enumerate(s):\n        if ch in last and last[ch] >= left:\n            left = last[ch] + 1\n        last[ch] = right\n        ans = max(ans, right - left + 1)\n    return ans"},{"id":4,"title":"Median of Two Sorted Arrays","difficulty":"Hard","pattern":"Binary Search","trigger":"Two sorted arrays must be combined conceptually without fully merging.","anti":"If O(m+n) time is acceptable, simply merge; the hard constraint is logarithmic time.","insight":"Binary-search a partition in the smaller array so max(left) <= min(right).","brute":"O(m+n), O(m+n) if fully merged.","opt":"O(log(min(m,n))), O(1).","pitfalls":"Partition indices may be 0 or at the end; use ±infinity sentinels.","code":"def find_median_sorted_arrays(a: list[int], b: list[int]) -> float:\n    if len(a) > len(b):\n        a, b = b, a\n    m, n = len(a), len(b)\n    lo, hi = 0, m\n    while lo <= hi:\n        i = (lo + hi) // 2\n        j = (m + n + 1) // 2 - i\n        al = float(\"-inf\") if i == 0 else a[i - 1]\n        ar = float(\"inf\") if i == m else a[i]\n        bl = float(\"-inf\") if j == 0 else b[j - 1]\n        br = float(\"inf\") if j == n else b[j]\n        if al <= br and bl <= ar:\n            if (m + n) % 2:\n                return max(al, bl)\n            return (max(al, bl) + min(ar, br)) / 2\n        if al > br:\n            hi = i - 1\n        else:\n            lo = i + 1\n    raise ValueError(\"Invalid input\")"},{"id":5,"title":"Longest Palindromic Substring","difficulty":"Medium","pattern":"Expand Around Center","trigger":"Longest contiguous substring that reads the same forward/backward.","anti":"Manacher is better only when strict O(n) time is required; DP is usually more space than needed.","insight":"Every palindrome has a center: one character or the gap between two characters.","brute":"O(n³) naive substring generation/checking.","opt":"O(n²) time, O(1) extra space.","pitfalls":"Check both odd and even centers; return the actual substring.","code":"def longest_palindrome(s: str) -> str:\n    best = \"\"\n    def expand(l: int, r: int) -> None:\n        nonlocal best\n        while l >= 0 and r < len(s) and s[l] == s[r]:\n            l -= 1; r += 1\n        if r - l - 1 > len(best):\n            best = s[l + 1:r]\n    for i in range(len(s)):\n        expand(i, i)\n        expand(i, i + 1)\n    return best"},{"id":6,"title":"Zigzag Conversion","difficulty":"Medium","pattern":"Simulation","trigger":"Characters are written down/up across rows in a repeating zigzag.","anti":"Direct index arithmetic is possible, but is easier to get wrong for edge row counts.","insight":"Simulate row movement with a direction; append each character to its row.","brute":"O(n), O(n): required output storage.","opt":"O(n), O(n): simulate rows.","pitfalls":"numRows == 1 or >= len(s) returns s.","code":"def convert(s: str, num_rows: int) -> str:\n    if num_rows == 1 or num_rows >= len(s):\n        return s\n    rows = [\"\"] * num_rows\n    r, step = 0, 1\n    for ch in s:\n        rows[r] += ch\n        if r == 0: step = 1\n        elif r == num_rows - 1: step = -1\n        r += step\n    return \"\".join(rows)"},{"id":7,"title":"Reverse Integer","difficulty":"Medium","pattern":"Math / Digits","trigger":"Reverse decimal digits while respecting a fixed 32-bit signed range.","anti":"String conversion is simple but misses the intended arithmetic technique in interviews.","insight":"Repeatedly take the last digit with modulo and append it to the result.","brute":"O(log |x|) time, O(log |x|) space if converted to a string.","opt":"O(log |x|) time, O(1) space.","pitfalls":"Check overflow before multiplying by 10 and adding the digit.","code":"def reverse(x: int) -> int:\n    sign = -1 if x < 0 else 1\n    x = abs(x)\n    out = 0\n    while x:\n        x, digit = divmod(x, 10)\n        out = out * 10 + digit\n    out *= sign\n    return out if -(2**31) <= out <= 2**31 - 1 else 0"},{"id":8,"title":"String to Integer (atoi)","difficulty":"Medium","pattern":"String Parsing","trigger":"The prompt specifies whitespace, sign, digits, stopping rules, and clamping.","anti":"Using int(s) bypasses the parsing exercise and may violate the required behavior.","insight":"Parse a deterministic prefix: skip spaces, read sign, then digits, then clamp.","brute":"O(n), O(n) with transformed/parsed copies.","opt":"O(n), O(1).","pitfalls":"Stop at the first non-digit after the numeric prefix; clamp to 32-bit bounds.","code":"def my_atoi(s: str) -> int:\n    i, n = 0, len(s)\n    while i < n and s[i] == \" \":\n        i += 1\n    sign = 1\n    if i < n and s[i] in \"+-\":\n        sign = -1 if s[i] == \"-\" else 1\n        i += 1\n    out = 0\n    limit = 2**31 - 1 if sign == 1 else 2**31\n    while i < n and s[i].isdigit():\n        out = min(limit, out * 10 + int(s[i]))\n        i += 1\n    return sign * out"},{"id":9,"title":"Palindrome Number","difficulty":"Easy","pattern":"Two Pointers","trigger":"A number must be checked as a palindrome without unnecessary string work.","anti":"String conversion is fine when no arithmetic constraint exists, but the arithmetic solution is more interview-relevant.","insight":"Reverse only half the digits and compare the two halves.","brute":"O(d) time, O(d) space as a string.","opt":"O(d) time, O(1) space.","pitfalls":"Negative numbers and numbers ending in zero (except zero) cannot be palindromes.","code":"def is_palindrome_number(x: int) -> bool:\n    if x < 0 or (x % 10 == 0 and x != 0):\n        return False\n    rev = 0\n    while x > rev:\n        x, digit = divmod(x, 10)\n        rev = rev * 10 + digit\n    return x == rev or x == rev // 10"},{"id":11,"title":"Container With Most Water","difficulty":"Medium","pattern":"Two Pointers","trigger":"Choose two array positions maximizing width × limiting height.","anti":"Brute-force pairs are O(n²); sorting destroys the original positions and is unnecessary.","insight":"After using left/right, move the shorter side because moving the taller side cannot increase the limiting height.","brute":"O(n²), O(1).","opt":"O(n), O(1).","pitfalls":"Area is width times min height; move only the shorter wall.","code":"def max_area(height: list[int]) -> int:\n    l, r, ans = 0, len(height) - 1, 0\n    while l < r:\n        ans = max(ans, (r - l) * min(height[l], height[r]))\n        if height[l] < height[r]:\n            l += 1\n        else:\n            r -= 1\n    return ans"},{"id":13,"title":"Roman to Integer","difficulty":"Easy","pattern":"Greedy / Scanning","trigger":"Symbols have values and certain smaller-before-larger pairs represent subtraction.","anti":"A full map with case-by-case pair strings works, but scanning with a lookahead is simpler.","insight":"Subtract a value when it is smaller than the next symbol; otherwise add it.","brute":"O(n) time, O(n) space if converted to pairs.","opt":"O(n) time, O(1) space.","pitfalls":"Only the specified subtractive combinations are valid.","code":"def roman_to_int(s: str) -> int:\n    v = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}\n    ans = 0\n    for i, ch in enumerate(s):\n        ans += -v[ch] if i + 1 < len(s) and v[ch] < v[s[i+1]] else v[ch]\n    return ans"},{"id":14,"title":"Longest Common Prefix","difficulty":"Easy","pattern":"String / Scanning","trigger":"Find the common prefix shared by every string.","anti":"Sorting is unnecessary when you can compare against the first string.","insight":"Shrink the candidate prefix until every string starts with it.","brute":"O(n·m) time, O(m) if constructing copies.","opt":"O(n·m) time, O(m) for the answer.","pitfalls":"Empty input and an empty common prefix are valid.","code":"def longest_common_prefix(strs: list[str]) -> str:\n    if not strs:\n        return \"\"\n    prefix = strs[0]\n    for s in strs[1:]:\n        while not s.startswith(prefix):\n            prefix = prefix[:-1]\n            if not prefix:\n                return \"\"\n    return prefix"},{"id":15,"title":"3Sum","difficulty":"Medium","pattern":"Sort + Two Pointers","trigger":"Find triples summing to a target (usually zero) and return unique combinations.","anti":"Hashing can work, but without sorting duplicate handling becomes more complex.","insight":"Sort; fix one element; solve the remaining two-sum with two pointers.","brute":"O(n³), O(1) extra.","opt":"O(n²), O(1) extra beyond output.","pitfalls":"Skip duplicate fixed values and duplicate left/right values.","code":"def three_sum(nums: list[int]) -> list[list[int]]:\n    nums.sort()\n    out = []\n    for i in range(len(nums) - 2):\n        if i and nums[i] == nums[i-1]: continue\n        l, r = i + 1, len(nums) - 1\n        while l < r:\n            s = nums[i] + nums[l] + nums[r]\n            if s == 0:\n                out.append([nums[i], nums[l], nums[r]])\n                l += 1; r -= 1\n                while l < r and nums[l] == nums[l-1]: l += 1\n                while l < r and nums[r] == nums[r+1]: r -= 1\n            elif s < 0: l += 1\n            else: r -= 1\n    return out"},{"id":16,"title":"3Sum Closest","difficulty":"Medium","pattern":"Sort + Two Pointers","trigger":"Three numbers must get as close as possible to a target.","anti":"O(n³) enumeration is too slow for typical constraints.","insight":"Sort, fix one number, and move two pointers based on whether the sum is below/above target.","brute":"O(n³), O(1).","opt":"O(n²), O(1) extra.","pitfalls":"Initialize the best before comparing; return the sum, not the indices.","code":"def three_sum_closest(nums: list[int], target: int) -> int:\n    nums.sort()\n    best = nums[0] + nums[1] + nums[2]\n    for i in range(len(nums) - 2):\n        l, r = i + 1, len(nums) - 1\n        while l < r:\n            s = nums[i] + nums[l] + nums[r]\n            if abs(s-target) < abs(best-target): best = s\n            if s < target: l += 1\n            elif s > target: r -= 1\n            else: return s\n    return best"},{"id":17,"title":"Letter Combinations of a Phone Number","difficulty":"Medium","pattern":"Backtracking","trigger":"Generate all strings formed by one letter choice for each digit.","anti":"If every combination must be returned, brute-force enumeration is essentially unavoidable; the key is clean generation.","insight":"At each digit, choose one mapped letter, recurse, then undo.","brute":"O(4^n·n) output work.","opt":"O(4^n·n) including output; O(n) recursion.","pitfalls":"Empty input returns []; don't reuse a mutable path without backtracking.","code":"def letter_combinations(digits: str) -> list[str]:\n    if not digits: return []\n    mp = {'2':'abc','3':'def','4':'ghi','5':'jkl','6':'mno','7':'pqrs','8':'tuv','9':'wxyz'}\n    out, path = [], []\n    def bt(i: int):\n        if i == len(digits):\n            out.append(''.join(path)); return\n        for ch in mp[digits[i]]:\n            path.append(ch); bt(i+1); path.pop()\n    bt(0)\n    return out"},{"id":18,"title":"4Sum","difficulty":"Medium","pattern":"Sort + Two Pointers","trigger":"Find unique quadruplets satisfying a target sum.","anti":"Enumerating four indices is O(n⁴).","insight":"Sort; fix two positions; reduce the remainder to two pointers.","brute":"O(n⁴), O(1).","opt":"O(n³), O(1) extra beyond output.","pitfalls":"Skip duplicates at both fixed levels and after a match.","code":"def four_sum(nums: list[int], target: int) -> list[list[int]]:\n    nums.sort(); out = []; n = len(nums)\n    for i in range(n-3):\n        if i and nums[i] == nums[i-1]: continue\n        for j in range(i+1, n-2):\n            if j > i+1 and nums[j] == nums[j-1]: continue\n            l, r = j+1, n-1\n            while l < r:\n                s = nums[i]+nums[j]+nums[l]+nums[r]\n                if s == target:\n                    out.append([nums[i],nums[j],nums[l],nums[r]])\n                    l += 1; r -= 1\n                    while l < r and nums[l] == nums[l-1]: l += 1\n                    while l < r and nums[r] == nums[r+1]: r -= 1\n                elif s < target: l += 1\n                else: r -= 1\n    return out"},{"id":19,"title":"Remove Nth Node From End of List","difficulty":"Medium","pattern":"Fast/Slow Pointers","trigger":"Remove a node counted from the end without first computing length.","anti":"Two passes also work, but the one-pass two-pointer solution is cleaner.","insight":"Keep fast n nodes ahead; when fast reaches the end, slow is just before the target.","brute":"O(n), O(1) with two passes.","opt":"O(n), O(1) one pass.","pitfalls":"Use a dummy node so removing the head is identical to other removals.","code":"def remove_nth_from_end(head, n):\n    dummy = ListNode(0, head)\n    slow = fast = dummy\n    for _ in range(n): fast = fast.next\n    while fast.next:\n        slow = slow.next; fast = fast.next\n    slow.next = slow.next.next\n    return dummy.next"},{"id":20,"title":"Valid Parentheses","difficulty":"Easy","pattern":"Stack","trigger":"Opening brackets must be matched in reverse nesting order.","anti":"Counting opens/closes cannot distinguish nesting types.","insight":"A stack stores unmatched opening brackets; each close must match the top.","brute":"O(n), O(n).","opt":"O(n), O(n).","pitfalls":"An early mismatch is failure; stack must be empty at the end.","code":"def is_valid(s: str) -> bool:\n    pairs = {')':'(', ']':'[', '}':'{'}\n    stack = []\n    for ch in s:\n        if ch in pairs:\n            if not stack or stack.pop() != pairs[ch]:\n                return False\n        else:\n            stack.append(ch)\n    return not stack"},{"id":21,"title":"Merge Two Sorted Lists","difficulty":"Easy","pattern":"Two Pointers","trigger":"Merge two sorted linked lists while preserving sorted order.","anti":"Concatenate and sort is O(n log n) and wastes the sorted input property.","insight":"Always attach the smaller current node and advance that list.","brute":"O(n log n), O(n) if collecting and sorting.","opt":"O(n+m), O(1) extra.","pitfalls":"Use a dummy node and attach the remaining suffix directly.","code":"def merge_two_lists(a, b):\n    dummy = cur = ListNode(0)\n    while a and b:\n        if a.val <= b.val:\n            cur.next, a = a, a.next\n        else:\n            cur.next, b = b, b.next\n        cur = cur.next\n    cur.next = a or b\n    return dummy.next"},{"id":22,"title":"Generate Parentheses","difficulty":"Medium","pattern":"Backtracking","trigger":"Generate every balanced parenthesis string of length 2n.","anti":"Generating all 2^(2n) strings and filtering is wasteful.","insight":"Only add '(' while opens < n and ')' while closes < opens.","brute":"O(2^(2n)·n) candidates.","opt":"O(Cn·n) output-scale time; O(n) recursion excluding output.","pitfalls":"Never allow closes > opens; copy the path at completion.","code":"def generate_parenthesis(n: int) -> list[str]:\n    out, path = [], []\n    def bt(opens: int, closes: int):\n        if len(path) == 2*n:\n            out.append(''.join(path)); return\n        if opens < n:\n            path.append('('); bt(opens+1, closes); path.pop()\n        if closes < opens:\n            path.append(')'); bt(opens, closes+1); path.pop()\n    bt(0, 0)\n    return out"},{"id":23,"title":"Merge k Sorted Lists","difficulty":"Hard","pattern":"Heap","trigger":"Merge many sorted streams/lists into one sorted stream.","anti":"Repeated pairwise merging can be O(Nk).","insight":"Keep the smallest current node from each list in a min-heap.","brute":"O(Nk) repeated merging.","opt":"O(N log k), O(k) heap.","pitfalls":"Heap entries need a comparable tie-breaker when node values are equal.","code":"import heapq\ndef merge_k_lists(lists):\n    heap, serial = [], 0\n    for node in lists:\n        if node:\n            heapq.heappush(heap, (node.val, serial, node)); serial += 1\n    dummy = cur = ListNode(0)\n    while heap:\n        _, _, node = heapq.heappop(heap)\n        cur.next = node; cur = node\n        if node.next:\n            heapq.heappush(heap, (node.next.val, serial, node.next)); serial += 1\n    return dummy.next"},{"id":26,"title":"Remove Duplicates from Sorted Array","difficulty":"Easy","pattern":"Two Pointers","trigger":"Sorted array must be deduplicated in-place.","anti":"Using a set loses the in-place requirement and changes memory complexity.","insight":"Write each newly encountered value at the next unique position.","brute":"O(n) time, O(n) space with a set.","opt":"O(n) time, O(1) space.","pitfalls":"Return the new length; only the prefix matters.","code":"def remove_duplicates(nums: list[int]) -> int:\n    if not nums: return 0\n    w = 1\n    for r in range(1, len(nums)):\n        if nums[r] != nums[r-1]:\n            nums[w] = nums[r]; w += 1\n    return w"},{"id":27,"title":"Remove Element","difficulty":"Easy","pattern":"Two Pointers","trigger":"Remove all occurrences of a value in-place.","anti":"Building a filtered list uses extra memory.","insight":"Maintain a write pointer for elements that should remain.","brute":"O(n) time, O(n) extra if filtering.","opt":"O(n) time, O(1) extra.","pitfalls":"Only the first returned-length positions are relevant.","code":"def remove_element(nums: list[int], val: int) -> int:\n    w = 0\n    for x in nums:\n        if x != val:\n            nums[w] = x; w += 1\n    return w"},{"id":28,"title":"Find the Index of the First Occurrence in a String","difficulty":"Easy","pattern":"String Scanning","trigger":"Find a pattern's first occurrence in a text.","anti":"A naive scan is O(nm); KMP is useful when worst-case linear time is required.","insight":"Try each start position, or use KMP when constraints demand it.","brute":"O(nm), O(1).","opt":"O(nm) simple; O(n+m) with KMP.","pitfalls":"Empty pattern semantics depend on the problem; do not forget the no-match case.","code":"def str_str(haystack: str, needle: str) -> int:\n    if not needle: return 0\n    for i in range(len(haystack) - len(needle) + 1):\n        if haystack[i:i+len(needle)] == needle:\n            return i\n    return -1"},{"id":31,"title":"Next Permutation","difficulty":"Medium","pattern":"Array Transformation","trigger":"Transform an arrangement into the lexicographically next larger arrangement in-place.","anti":"Generate permutations and sort is factorial time.","insight":"Find the rightmost ascent, swap with the smallest larger suffix value, then reverse the suffix.","brute":"O(n!), O(n) generation.","opt":"O(n), O(1).","pitfalls":"The suffix is non-increasing before the transformation; reverse it after the swap.","code":"def next_permutation(nums: list[int]) -> None:\n    i = len(nums) - 2\n    while i >= 0 and nums[i] >= nums[i+1]: i -= 1\n    if i >= 0:\n        j = len(nums) - 1\n        while nums[j] <= nums[i]: j -= 1\n        nums[i], nums[j] = nums[j], nums[i]\n    nums[i+1:] = reversed(nums[i+1:])"},{"id":32,"title":"Longest Valid Parentheses","difficulty":"Hard","pattern":"Stack / DP","trigger":"Find the longest contiguous valid-parentheses substring.","anti":"Checking every substring is O(n²) or worse.","insight":"Use indices of unmatched '('; a sentinel anchors valid lengths.","brute":"O(n²), O(1) naive.","opt":"O(n), O(n) stack; O(n), O(1) with DP/two scans.","pitfalls":"Reset the boundary after an unmatched ')'; lengths are index differences.","code":"def longest_valid_parentheses(s: str) -> int:\n    stack = [-1]\n    ans = 0\n    for i, ch in enumerate(s):\n        if ch == '(':\n            stack.append(i)\n        else:\n            stack.pop()\n            if not stack:\n                stack.append(i)\n            else:\n                ans = max(ans, i - stack[-1])\n    return ans"},{"id":33,"title":"Search in Rotated Sorted Array","difficulty":"Medium","pattern":"Binary Search","trigger":"Sorted array has one rotation; search in O(log n).","anti":"Linear scan ignores the sorted structure.","insight":"At every midpoint, one half is still sorted; decide whether target lies in that half.","brute":"O(n), O(1).","opt":"O(log n), O(1).","pitfalls":"Compare target against the sorted half's endpoints.","code":"def search_rotated(nums: list[int], target: int) -> int:\n    l, r = 0, len(nums)-1\n    while l <= r:\n        m = (l+r)//2\n        if nums[m] == target: return m\n        if nums[l] <= nums[m]:\n            if nums[l] <= target < nums[m]: r = m-1\n            else: l = m+1\n        else:\n            if nums[m] < target <= nums[r]: l = m+1\n            else: r = m-1\n    return -1"},{"id":34,"title":"Find First and Last Position of Element in Sorted Array","difficulty":"Medium","pattern":"Binary Search / Boundary","trigger":"Find the first and last occurrence in sorted data.","anti":"Scanning outward can be O(n).","insight":"Run two boundary binary searches: first >= target and first > target.","brute":"O(n), O(1).","opt":"O(log n), O(1).","pitfalls":"Keep boundary semantics consistent; return [-1,-1] when absent.","code":"def search_range(nums: list[int], target: int) -> list[int]:\n    def lower(x):\n        l, r = 0, len(nums)\n        while l < r:\n            m=(l+r)//2\n            if nums[m] < x: l=m+1\n            else: r=m\n        return l\n    a = lower(target)\n    b = lower(target+1)-1\n    return [a,b] if a < len(nums) and nums[a] == target else [-1,-1]"},{"id":35,"title":"Search Insert Position","difficulty":"Easy","pattern":"Binary Search / Boundary","trigger":"Find where a target belongs in sorted order.","anti":"Linear scan is O(n).","insight":"Find the first index whose value is >= target.","brute":"O(n), O(1).","opt":"O(log n), O(1).","pitfalls":"Return len(nums) when target is larger than every element.","code":"def search_insert(nums: list[int], target: int) -> int:\n    l, r = 0, len(nums)\n    while l < r:\n        m=(l+r)//2\n        if nums[m] < target: l=m+1\n        else: r=m\n    return l"},{"id":39,"title":"Combination Sum","difficulty":"Medium","pattern":"Backtracking","trigger":"Find all combinations summing to target when choices can be reused.","anti":"Enumerating all subsets and sums blindly creates huge unnecessary search.","insight":"Sort choices and recurse from the current index; prune when candidate > remaining target.","brute":"Exponential output/search space.","opt":"Exponential in target/input; O(target/min(c)) recursion depth.","pitfalls":"Keep the same index for reuse; advance it for the next distinct choice.","code":"def combination_sum(candidates: list[int], target: int) -> list[list[int]]:\n    candidates.sort(); out=[]; path=[]\n    def bt(start, remain):\n        if remain == 0:\n            out.append(path.copy()); return\n        for i in range(start, len(candidates)):\n            x=candidates[i]\n            if x > remain: break\n            path.append(x); bt(i, remain-x); path.pop()\n    bt(0,target)\n    return out"},{"id":41,"title":"First Missing Positive","difficulty":"Hard","pattern":"Index-as-Hash","trigger":"Find the smallest missing positive using O(n) time and O(1) extra space.","anti":"A set is O(n) space; sorting is O(n log n).","insight":"Place value x into index x-1 whenever 1 <= x <= n, then scan.","brute":"O(n) with set; O(n log n) sorting.","opt":"O(n) time, O(1) extra.","pitfalls":"Ignore non-positive/out-of-range values; avoid infinite swaps on duplicates.","code":"def first_missing_positive(nums: list[int]) -> int:\n    n=len(nums); i=0\n    while i<n:\n        x=nums[i]\n        if 1<=x<=n and nums[x-1]!=x:\n            nums[i],nums[x-1]=nums[x-1],nums[i]\n        else:\n            i+=1\n    for i,x in enumerate(nums,1):\n        if x!=i: return i\n    return n+1"},{"id":42,"title":"Trapping Rain Water","difficulty":"Hard","pattern":"Two Pointers","trigger":"Water above each bar depends on max wall on both sides.","anti":"Prefix/suffix max arrays use O(n) extra memory.","insight":"Process the side with the smaller boundary because its water level is already determined.","brute":"O(n) time, O(n) space with prefix/suffix maxima.","opt":"O(n), O(1).","pitfalls":"Update max before calculating trapped water; move the lower side.","code":"def trap(height: list[int]) -> int:\n    l,r=0,len(height)-1\n    lm=rm=ans=0\n    while l<r:\n        if height[l] <= height[r]:\n            lm=max(lm,height[l]); ans += lm-height[l]; l+=1\n        else:\n            rm=max(rm,height[r]); ans += rm-height[r]; r-=1\n    return ans"},{"id":46,"title":"Permutations","difficulty":"Medium","pattern":"Backtracking","trigger":"Generate every ordering of distinct values.","anti":"There are n! outputs, so enumeration is inherent.","insight":"Choose an unused element, recurse, then undo.","brute":"O(n·n!) output generation.","opt":"O(n·n!) time, O(n) recursion plus output.","pitfalls":"Track used values; copy the path at each complete permutation.","code":"def permute(nums: list[int]) -> list[list[int]]:\n    out=[]; path=[]; used=[False]*len(nums)\n    def bt():\n        if len(path)==len(nums):\n            out.append(path.copy()); return\n        for i,x in enumerate(nums):\n            if used[i]: continue\n            used[i]=True; path.append(x); bt(); path.pop(); used[i]=False\n    bt(); return out"},{"id":48,"title":"Rotate Image","difficulty":"Medium","pattern":"Matrix Transformation","trigger":"Rotate an n×n matrix 90° in-place.","anti":"Creating another matrix is O(n²) space.","insight":"Transpose the matrix, then reverse each row.","brute":"O(n²), O(n²).","opt":"O(n²), O(1).","pitfalls":"Only works directly for square matrix; transpose direction matters.","code":"def rotate(matrix: list[list[int]]) -> None:\n    n=len(matrix)\n    for i in range(n):\n        for j in range(i+1,n):\n            matrix[i][j],matrix[j][i]=matrix[j][i],matrix[i][j]\n    for row in matrix:\n        row.reverse()"},{"id":49,"title":"Group Anagrams","difficulty":"Medium","pattern":"Hash Map","trigger":"Group strings with the same character multiset.","anti":"Pairwise comparison is O(n²·k).","insight":"Use a canonical key: sorted characters or a 26-count tuple.","brute":"O(n²·k) pairwise.","opt":"O(n·k log k) with sorted keys; O(n·k) with counts.","pitfalls":"The key must be deterministic; count tuple is faster for fixed lowercase alphabet.","code":"from collections import defaultdict\ndef group_anagrams(strs: list[str]) -> list[list[str]]:\n    groups=defaultdict(list)\n    for s in strs:\n        key=tuple(sorted(s))\n        groups[key].append(s)\n    return list(groups.values())"},{"id":50,"title":"Pow(x, n)","difficulty":"Medium","pattern":"Divide and Conquer","trigger":"Compute x^n efficiently for very large n.","anti":"Multiplying x n times is O(n).","insight":"Exponentiation by squaring halves the exponent each step.","brute":"O(n), O(1).","opt":"O(log n), O(1) iterative.","pitfalls":"Handle negative n and zero; use integer division by 2.","code":"def my_pow(x: float, n: int) -> float:\n    if n < 0: x, n = 1/x, -n\n    out = 1.0\n    while n:\n        if n & 1: out *= x\n        x *= x; n >>= 1\n    return out"},{"id":51,"title":"N-Queens","difficulty":"Hard","pattern":"Backtracking","trigger":"Place n queens so no two share a row, column, or diagonal.","anti":"Enumerating all board arrangements is n! or worse without pruning.","insight":"Place one queen per row and maintain occupied columns/diagonals.","brute":"Brute force is roughly O(n!) or worse.","opt":"Backtracking is exponential, with strong pruning; O(n) auxiliary sets.","pitfalls":"Diagonal keys are row-col and row+col; undo every choice.","code":"def solve_n_queens(n: int) -> list[list[str]]:\n    out=[]; cols=set(); d1=set(); d2=set(); board=[['.']*n for _ in range(n)]\n    def bt(r):\n        if r==n:\n            out.append([''.join(row) for row in board]); return\n        for c in range(n):\n            if c in cols or r-c in d1 or r+c in d2: continue\n            cols.add(c); d1.add(r-c); d2.add(r+c); board[r][c]='Q'\n            bt(r+1)\n            board[r][c]='.'; cols.remove(c); d1.remove(r-c); d2.remove(r+c)\n    bt(0); return out"},{"id":53,"title":"Maximum Subarray","difficulty":"Medium","pattern":"Kadane / DP","trigger":"Find the contiguous subarray with maximum sum.","anti":"Enumerating all subarrays is O(n²).","insight":"At each index, either extend the current subarray or start fresh here.","brute":"O(n²), O(1).","opt":"O(n), O(1).","pitfalls":"Do not reset incorrectly when all values are negative; initialize from the first value.","code":"def max_sub_array(nums: list[int]) -> int:\n    cur=best=nums[0]\n    for x in nums[1:]:\n        cur=max(x,cur+x); best=max(best,cur)\n    return best"},{"id":54,"title":"Spiral Matrix","difficulty":"Medium","pattern":"Matrix / Simulation","trigger":"Traverse a matrix in spiral order without revisiting cells.","anti":"Visited-cell simulation uses O(mn) extra memory.","insight":"Maintain top/bottom/left/right boundaries and peel layers.","brute":"O(mn), O(mn) visited.","opt":"O(mn) time, O(1) extra beyond output.","pitfalls":"After each boundary traversal, check whether the remaining row/column still exists.","code":"def spiral_order(matrix: list[list[int]]) -> list[int]:\n    if not matrix: return []\n    t,b,l,r=0,len(matrix)-1,0,len(matrix[0])-1; out=[]\n    while t<=b and l<=r:\n        for c in range(l,r+1): out.append(matrix[t][c])\n        t+=1\n        for i in range(t,b+1): out.append(matrix[i][r])\n        r-=1\n        if t<=b:\n            for c in range(r,l-1,-1): out.append(matrix[b][c])\n            b-=1\n        if l<=r:\n            for i in range(b,t-1,-1): out.append(matrix[i][l])\n            l+=1\n    return out"},{"id":55,"title":"Jump Game","difficulty":"Medium","pattern":"Greedy","trigger":"Determine whether the end is reachable with variable jump lengths.","anti":"DFS/DP explores many overlapping states.","insight":"Track the farthest reachable index; if current index exceeds it, fail.","brute":"O(n²) DP.","opt":"O(n) time, O(1) space.","pitfalls":"You only need the farthest reachable boundary, not every path.","code":"def can_jump(nums: list[int]) -> bool:\n    reach=0\n    for i,x in enumerate(nums):\n        if i>reach: return False\n        reach=max(reach,i+x)\n    return True"},{"id":56,"title":"Merge Intervals","difficulty":"Medium","pattern":"Intervals / Sweep","trigger":"Merge overlapping closed intervals.","anti":"Comparing every pair is O(n²).","insight":"Sort by start, then merge into the last interval when overlap exists.","brute":"O(n²), O(n).","opt":"O(n log n), O(n) output.","pitfalls":"Sort first; overlap is start <= previous end.","code":"def merge_intervals(intervals: list[list[int]]) -> list[list[int]]:\n    intervals.sort(); out=[]\n    for s,e in intervals:\n        if not out or s>out[-1][1]: out.append([s,e])\n        else: out[-1][1]=max(out[-1][1],e)\n    return out"},{"id":62,"title":"Unique Paths","difficulty":"Medium","pattern":"Dynamic Programming","trigger":"Count grid paths moving only right/down.","anti":"Enumerating all paths is exponential.","insight":"dp[r][c] = paths from top/left; compress to one row.","brute":"Exponential recursion.","opt":"O(mn) time, O(n) space.","pitfalls":"Boundary row/column has exactly one path.","code":"def unique_paths(m: int, n: int) -> int:\n    dp=[1]*n\n    for _ in range(1,m):\n        for c in range(1,n): dp[c]+=dp[c-1]\n    return dp[-1]"},{"id":66,"title":"Plus One","difficulty":"Easy","pattern":"Array / Carry","trigger":"Increment a decimal number represented by digits.","anti":"Converting to an integer can overflow or violate the representation constraint.","insight":"Scan from right; carry through trailing 9s.","brute":"O(n), O(n) with conversion.","opt":"O(n) time, O(1) extra besides returned list.","pitfalls":"All 9s require prepending 1.","code":"def plus_one(digits: list[int]) -> list[int]:\n    for i in range(len(digits)-1,-1,-1):\n        if digits[i]<9:\n            digits[i]+=1; return digits\n        digits[i]=0\n    return [1]+digits"},{"id":67,"title":"Add Binary","difficulty":"Easy","pattern":"String / Carry","trigger":"Add two binary strings without integer conversion.","anti":"Converting to integers can overflow and defeats the exercise.","insight":"Two pointers from the end plus carry.","brute":"O(n), O(n).","opt":"O(n), O(n) output.","pitfalls":"Remember to append the final carry.","code":"def add_binary(a: str, b: str) -> str:\n    i,j=len(a)-1,len(b)-1; carry=0; out=[]\n    while i>=0 or j>=0 or carry:\n        total=carry+(ord(a[i])-48 if i>=0 else 0)+(ord(b[j])-48 if j>=0 else 0)\n        out.append(str(total&1)); carry=total>>1; i-=1; j-=1\n    return ''.join(reversed(out))"},{"id":69,"title":"Sqrt(x)","difficulty":"Easy","pattern":"Binary Search","trigger":"Find floor(sqrt(x)) without floating-point sqrt.","anti":"Linear increment is O(sqrt(x)).","insight":"Binary-search the largest mid with mid² <= x.","brute":"O(sqrt(x)), O(1).","opt":"O(log x), O(1).","pitfalls":"Use division or compare safely if overflow is possible in fixed-width languages.","code":"def my_sqrt(x: int) -> int:\n    l,r=0,x\n    while l<=r:\n        m=(l+r)//2\n        if m*m<=x: l=m+1\n        else: r=m-1\n    return r"},{"id":70,"title":"Climbing Stairs","difficulty":"Easy","pattern":"Dynamic Programming","trigger":"Count ways to reach step n using 1- or 2-step moves.","anti":"Recursive branching is exponential.","insight":"The recurrence is Fibonacci: dp[n]=dp[n-1]+dp[n-2].","brute":"O(2^n) recursion.","opt":"O(n) time; O(1) space.","pitfalls":"Base cases n=1 and n=2.","code":"def climb_stairs(n: int) -> int:\n    a,b=1,1\n    for _ in range(n): a,b=b,a+b\n    return a"},{"id":71,"title":"Simplify Path","difficulty":"Medium","pattern":"Stack","trigger":"Normalize Unix-style path components '.', '..', and redundant slashes.","anti":"Repeated string manipulation can be error-prone.","insight":"Split on '/', push normal components, pop for '..'.","brute":"O(n), O(n) with ad-hoc reconstruction.","opt":"O(n), O(n) stack.","pitfalls":"Do not pop past root; ignore empty and '.' components.","code":"def simplify_path(path: str) -> str:\n    stack=[]\n    for part in path.split('/'):\n        if part in ('','.'): continue\n        if part=='..':\n            if stack: stack.pop()\n        else: stack.append(part)\n    return '/'+'/'.join(stack)"},{"id":73,"title":"Set Matrix Zeroes","difficulty":"Medium","pattern":"Matrix In-place Marking","trigger":"If a cell is zero, zero its entire row and column in-place.","anti":"A separate set of rows/columns uses O(m+n) space.","insight":"Use first row and first column as marker storage, plus two flags.","brute":"O(mn), O(m+n).","opt":"O(mn), O(1).","pitfalls":"Do not overwrite markers before using them; remember whether first row/column originally contained zero.","code":"def set_zeroes(matrix: list[list[int]]) -> None:\n    m,n=len(matrix),len(matrix[0])\n    row0=any(matrix[0][c]==0 for c in range(n))\n    col0=any(matrix[r][0]==0 for r in range(m))\n    for r in range(1,m):\n        for c in range(1,n):\n            if matrix[r][c]==0: matrix[r][0]=matrix[0][c]=0\n    for r in range(1,m):\n        for c in range(1,n):\n            if matrix[r][0]==0 or matrix[0][c]==0: matrix[r][c]=0\n    if row0:\n        for c in range(n): matrix[0][c]=0\n    if col0:\n        for r in range(m): matrix[r][0]=0"},{"id":75,"title":"Sort Colors","difficulty":"Medium","pattern":"Dutch National Flag","trigger":"Sort an array containing only 0, 1, 2 in one pass/in-place.","anti":"General sorting is O(n log n).","insight":"Maintain low, mid, high regions and place each color into its region.","brute":"O(n log n), O(1).","opt":"O(n), O(1).","pitfalls":"After swapping a 0 or 2, reconsider the new mid value appropriately.","code":"def sort_colors(nums: list[int]) -> None:\n    lo=mid=0; hi=len(nums)-1\n    while mid<=hi:\n        if nums[mid]==0:\n            nums[lo],nums[mid]=nums[mid],nums[lo]; lo+=1; mid+=1\n        elif nums[mid]==1:\n            mid+=1\n        else:\n            nums[mid],nums[hi]=nums[hi],nums[mid]; hi-=1"},{"id":76,"title":"Minimum Window Substring","difficulty":"Hard","pattern":"Sliding Window","trigger":"Find the shortest substring containing all required characters with multiplicity.","anti":"Checking every substring is O(n²).","insight":"Expand until all requirements are met, then shrink from the left while valid.","brute":"O(n²) naive.","opt":"O(n), O(k) with frequency maps.","pitfalls":"Track required counts and a 'formed' count; duplicates matter.","code":"from collections import Counter\ndef min_window(s: str, t: str) -> str:\n    need=Counter(t); have={}; formed=0; required=len(need); l=0; best=(float('inf'),0,0)\n    for r,ch in enumerate(s):\n        have[ch]=have.get(ch,0)+1\n        if ch in need and have[ch]==need[ch]: formed+=1\n        while formed==required:\n            if r-l+1<best[0]: best=(r-l+1,l,r+1)\n            x=s[l]; have[x]-=1\n            if x in need and have[x]<need[x]: formed-=1\n            l+=1\n    return s[best[1]:best[2]] if best[0]!=float('inf') else "},{"id":77,"title":"Combinations","difficulty":"Medium","pattern":"Backtracking","trigger":"Generate all k-element subsets from 1..n.","anti":"Enumerating all 2^n subsets then filtering k is wasteful.","insight":"Choose increasing values so each combination is generated once.","brute":"O(2^n), filtering.","opt":"O(C(n,k)·k) output time; O(k) recursion.","pitfalls":"Start next choice at i+1; prune when insufficient values remain.","code":"def combine(n: int, k: int) -> list[list[int]]:\n    out=[]; path=[]\n    def bt(start):\n        if len(path)==k: out.append(path.copy()); return\n        for x in range(start,n+1):\n            path.append(x); bt(x+1); path.pop()\n    bt(1); return out"},{"id":78,"title":"Subsets","difficulty":"Medium","pattern":"Backtracking","trigger":"Generate the power set.","anti":"Brute-force bit masks are fine, but backtracking exposes the reusable template.","insight":"At each index choose or skip the value.","brute":"O(2^n·n) output.","opt":"O(2^n·n) output, O(n) recursion.","pitfalls":"Copy each completed path; include the empty subset.","code":"def subsets(nums: list[int]) -> list[list[int]]:\n    out=[]; path=[]\n    def bt(i):\n        if i==len(nums): out.append(path.copy()); return\n        bt(i+1)\n        path.append(nums[i]); bt(i+1); path.pop()\n    bt(0); return out"},{"id":79,"title":"Word Search","difficulty":"Medium","pattern":"Backtracking / Grid","trigger":"Find whether a word can be formed by adjacent cells without reusing a cell.","anti":"Starting a fresh search from every cell without pruning is exponential but necessary in worst case.","insight":"DFS from matching cells while marking the current path as visited.","brute":"O(mn·4^L), O(mn) visited.","opt":"O(mn·4^L) worst case, O(L) path state with in-place marking.","pitfalls":"Restore the cell after recursion; don't reuse the same cell in one path.","code":"def exist(board: list[list[str]], word: str) -> bool:\n    m,n=len(board),len(board[0])\n    def dfs(r,c,i):\n        if i==len(word): return True\n        if r<0 or r>=m or c<0 or c>=n or board[r][c]!=word[i]: return False\n        ch=board[r][c]; board[r][c]='#'\n        ok=any(dfs(r+dr,c+dc,i+1) for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)))\n        board[r][c]=ch\n        return ok\n    return any(dfs(r,c,0) for r in range(m) for c in range(n))"},{"id":84,"title":"Largest Rectangle in Histogram","difficulty":"Hard","pattern":"Monotonic Stack","trigger":"Find the largest rectangle under histogram bars.","anti":"Expanding from each bar can be O(n²).","insight":"A monotonic increasing stack finds the first smaller bar that ends each rectangle.","brute":"O(n²), O(1).","opt":"O(n), O(n).","pitfalls":"Append a sentinel height 0 or flush the stack at the end; width uses popped index.","code":"def largest_rectangle_area(heights: list[int]) -> int:\n    stack=[]; ans=0\n    for i,h in enumerate(heights+[0]):\n        while stack and heights[stack[-1]]>h:\n            height=heights[stack.pop()]\n            left=stack[-1]+1 if stack else 0\n            ans=max(ans,height*(i-left))\n        stack.append(i)\n    return ans"},{"id":88,"title":"Merge Sorted Array","difficulty":"Easy","pattern":"Two Pointers","trigger":"Merge nums2 into nums1 in-place where nums1 has trailing capacity.","anti":"Merging into a new list violates the in-place goal.","insight":"Fill from the end so existing nums1 values are not overwritten.","brute":"O(m+n), O(m+n) extra.","opt":"O(m+n), O(1) extra.","pitfalls":"Compare from the back; remaining nums2 must be copied.","code":"def merge(nums1: list[int], m: int, nums2: list[int], n: int) -> None:\n    i,j,k=m-1,n-1,m+n-1\n    while j>=0:\n        if i>=0 and nums1[i]>nums2[j]:\n            nums1[k]=nums1[i]; i-=1\n        else:\n            nums1[k]=nums2[j]; j-=1\n        k-=1"},{"id":100,"title":"Same Tree","difficulty":"Easy","pattern":"Tree DFS","trigger":"Determine whether two binary trees have identical structure and values.","anti":"Serializing both trees works but uses extra memory.","insight":"Recursively compare current nodes and both children.","brute":"O(n), O(n) serialization.","opt":"O(n) time, O(h) recursion.","pitfalls":"Both None is true; exactly one None is false.","code":"def is_same_tree(p, q) -> bool:\n    if not p or not q: return p is q\n    return p.val==q.val and is_same_tree(p.left,q.left) and is_same_tree(p.right,q.right)"},{"id":101,"title":"Symmetric Tree","difficulty":"Easy","pattern":"Tree DFS","trigger":"Check whether a binary tree is a mirror of itself.","anti":"Serialization is possible but obscures the mirror relationship.","insight":"Compare left subtree of one side with right subtree of the other.","brute":"O(n), O(n) serialization.","opt":"O(n), O(h).","pitfalls":"Mirror means cross-comparing children, not comparing same-side children.","code":"def is_symmetric(root) -> bool:\n    def mirror(a,b):\n        if not a or not b: return a is b\n        return a.val==b.val and mirror(a.left,b.right) and mirror(a.right,b.left)\n    return True if not root else mirror(root.left,root.right)"},{"id":102,"title":"Binary Tree Level Order Traversal","difficulty":"Medium","pattern":"Tree BFS","trigger":"Process nodes level by level.","anti":"DFS can work but needs explicit depth bookkeeping.","insight":"Use a queue and process exactly the current queue length per level.","brute":"O(n), O(n).","opt":"O(n), O(w) queue.","pitfalls":"Capture len(queue) before processing a level.","code":"from collections import deque\ndef level_order(root):\n    if not root: return []\n    q=deque([root]); out=[]\n    while q:\n        level=[]\n        for _ in range(len(q)):\n            node=q.popleft(); level.append(node.val)\n            if node.left:q.append(node.left)\n            if node.right:q.append(node.right)\n        out.append(level)\n    return out"},{"id":108,"title":"Convert Sorted Array to Binary Search Tree","difficulty":"Easy","pattern":"Divide and Conquer","trigger":"Build a height-balanced BST from sorted data.","anti":"Inserting sequentially can create an unbalanced tree.","insight":"Choose the middle element as root and recurse on both halves.","brute":"O(n log n) with repeated insertion.","opt":"O(n) time, O(log n) recursion for balanced tree.","pitfalls":"Use midpoint consistently; any valid balanced midpoint choice is acceptable.","code":"def sorted_array_to_bst(nums: list[int]):\n    def build(l,r):\n        if l>r:return None\n        m=(l+r)//2\n        node=TreeNode(nums[m]); node.left=build(l,m-1); node.right=build(m+1,r)\n        return node\n    return build(0,len(nums)-1)"},{"id":118,"title":"Pascal's Triangle","difficulty":"Easy","pattern":"Dynamic Programming","trigger":"Generate rows where each interior value is the sum of two values above.","anti":"Recomputing each binomial coefficient independently wastes work.","insight":"Build each row from the previous row.","brute":"O(n³) naive coefficient computation.","opt":"O(n²) time, O(n²) output.","pitfalls":"First/last value in every row is 1.","code":"def generate(num_rows: int) -> list[list[int]]:\n    out=[]\n    for r in range(num_rows):\n        row=[1]*(r+1)\n        for c in range(1,r): row[c]=out[-1][c-1]+out[-1][c]\n        out.append(row)\n    return out"},{"id":121,"title":"Best Time to Buy and Sell Stock","difficulty":"Easy","pattern":"One-pass Greedy","trigger":"Maximize one buy/sell transaction.","anti":"Trying every buy/sell pair is O(n²).","insight":"Keep the cheapest price seen so far and best profit today.","brute":"O(n²), O(1).","opt":"O(n), O(1).","pitfalls":"Profit is sell - earlier buy; update minimum before future days.","code":"def max_profit(prices: list[int]) -> int:\n    low=prices[0]; ans=0\n    for p in prices[1:]:\n        ans=max(ans,p-low); low=min(low,p)\n    return ans"},{"id":122,"title":"Best Time to Buy and Sell Stock II","difficulty":"Medium","pattern":"Greedy","trigger":"Unlimited transactions, one share at a time.","anti":"Enumerating transaction schedules is exponential.","insight":"Capture every positive day-to-day gain.","brute":"O(2^n) schedule enumeration.","opt":"O(n), O(1).","pitfalls":"Do not double-count a falling segment; positive adjacent gains are equivalent to optimal valley-peak transactions.","code":"def max_profit_unlimited(prices: list[int]) -> int:\n    return sum(max(0,b-a) for a,b in zip(prices,prices[1:]))"},{"id":124,"title":"Binary Tree Maximum Path Sum","difficulty":"Hard","pattern":"Tree DP","trigger":"Find maximum sum of any path in a binary tree.","anti":"Enumerating all paths is O(n²) or worse.","insight":"Each node returns its best one-sided gain to its parent; separately update a path through both children.","brute":"O(n²) path enumeration.","opt":"O(n), O(h).","pitfalls":"Clamp child contributions at zero; global answer may be negative.","code":"def max_path_sum(root) -> int:\n    ans=float(\"-inf\")\n    def dfs(node):\n        nonlocal ans\n        if not node:return 0\n        left=max(0,dfs(node.left)); right=max(0,dfs(node.right))\n        ans=max(ans,node.val+left+right)\n        return node.val+max(left,right)\n    dfs(root); return ans"},{"id":125,"title":"Valid Palindrome","difficulty":"Easy","pattern":"Two Pointers","trigger":"Check whether a string is a palindrome ignoring non-alphanumeric characters and case.","anti":"Cleaning the entire string uses O(n) extra memory.","insight":"Compare normalized characters from both ends.","brute":"O(n), O(n).","opt":"O(n), O(1) extra.","pitfalls":"Skip punctuation on both sides; normalize case consistently.","code":"def is_palindrome(s: str) -> bool:\n    l,r=0,len(s)-1\n    while l<r:\n        while l<r and not s[l].isalnum():l+=1\n        while l<r and not s[r].isalnum():r-=1\n        if s[l].lower()!=s[r].lower():return False\n        l+=1;r-=1\n    return True"},{"id":127,"title":"Word Ladder","difficulty":"Hard","pattern":"BFS","trigger":"Find the shortest number of one-letter transformations between words.","anti":"DFS may find a path but not the shortest path efficiently.","insight":"Build wildcard buckets and BFS by transformation distance.","brute":"O(N·L²) or worse naive neighbor generation.","opt":"O(N·L²) preprocessing, O(N·L) BFS depending on representation.","pitfalls":"Mark words visited when enqueued; avoid revisiting buckets excessively.","code":"from collections import defaultdict, deque\ndef ladder_length(begin: str, end: str, word_list: list[str]) -> int:\n    words=set(word_list)\n    if end not in words:return 0\n    buckets=defaultdict(list)\n    for w in words:\n        for i in range(len(w)): buckets[w[:i]+'*'+w[i+1:]].append(w)\n    q=deque([(begin,1)]); seen={begin}\n    while q:\n        w,d=q.popleft()\n        if w==end:return d\n        for i in range(len(w)):\n            key=w[:i]+'*'+w[i+1:]\n            for nxt in buckets[key]:\n                if nxt not in seen: seen.add(nxt); q.append((nxt,d+1))\n            buckets[key].clear()\n    return 0"},{"id":128,"title":"Longest Consecutive Sequence","difficulty":"Medium","pattern":"Hash Set","trigger":"Find the longest run of consecutive integers in an unsorted array.","anti":"Sorting is O(n log n).","insight":"Start a sequence only when x-1 is absent, then walk forward.","brute":"O(n log n), O(1) after sort.","opt":"O(n) average, O(n) space.","pitfalls":"Only start from sequence beginnings to avoid repeated scans.","code":"def longest_consecutive(nums: list[int]) -> int:\n    s=set(nums); ans=0\n    for x in s:\n        if x-1 not in s:\n            y=x\n            while y in s:y+=1\n            ans=max(ans,y-x)\n    return ans"},{"id":129,"title":"Sum Root to Leaf Numbers","difficulty":"Medium","pattern":"Tree DFS","trigger":"Interpret each root-to-leaf path as a number and sum them.","anti":"Enumerating every path with strings creates extra work.","insight":"Carry the numeric prefix down the DFS.","brute":"O(nh) with path construction.","opt":"O(n), O(h).","pitfalls":"Only leaves contribute; update using prefix*10 + node.val.","code":"def sum_numbers(root) -> int:\n    def dfs(node, cur):\n        if not node:return 0\n        cur=cur*10+node.val\n        if not node.left and not node.right:return cur\n        return dfs(node.left,cur)+dfs(node.right,cur)\n    return dfs(root,0)"},{"id":131,"title":"Palindrome Partitioning","difficulty":"Medium","pattern":"Backtracking + Palindrome","trigger":"Partition a string into substrings where every part is a palindrome.","anti":"Enumerating all cuts and validating every partition repeatedly is expensive.","insight":"Backtrack over cut positions and test each candidate substring for palindrome.","brute":"Exponential.","opt":"O(n·2^n) typical bound with O(n) recursion plus output.","pitfalls":"Don't forget the final segment; copying path is required.","code":"def partition(s: str) -> list[list[str]]:\n    out=[]; path=[]\n    def pal(l,r): return s[l:r+1]==s[l:r+1][::-1]\n    def bt(i):\n        if i==len(s):out.append(path.copy());return\n        for j in range(i,len(s)):\n            if pal(i,j):\n                path.append(s[i:j+1]);bt(j+1);path.pop()\n    bt(0);return out"},{"id":136,"title":"Single Number","difficulty":"Easy","pattern":"Bit XOR","trigger":"Every value appears twice except one.","anti":"A set/count map uses O(n) space.","insight":"XOR cancels equal pairs because x ^ x = 0 and 0 ^ y = y.","brute":"O(n), O(n) set/count.","opt":"O(n), O(1).","pitfalls":"Relies on exactly two occurrences for every non-singleton value.","code":"def single_number(nums: list[int]) -> int:\n    ans=0\n    for x in nums: ans ^= x\n    return ans"},{"id":138,"title":"Copy List with Random Pointer","difficulty":"Medium","pattern":"Hash Map","trigger":"Deep-copy nodes where each node has next and arbitrary random references.","anti":"Copying only next pointers loses random relationships.","insight":"Map each original node to its clone, then wire next/random pointers.","brute":"O(n) time, O(n) map.","opt":"O(n) time, O(n) space.","pitfalls":"Create all clones before assigning cross-links.","code":"def copy_random_list(head):\n    if not head:return None\n    mp={}\n    cur=head\n    while cur:\n        mp[cur]=Node(cur.val);cur=cur.next\n    cur=head\n    while cur:\n        mp[cur].next=mp.get(cur.next)\n        mp[cur].random=mp.get(cur.random)\n        cur=cur.next\n    return mp[head]"},{"id":141,"title":"Linked List Cycle","difficulty":"Easy","pattern":"Fast/Slow Pointers","trigger":"Detect whether a linked list eventually points back to a previous node.","anti":"A visited set works but uses O(n) space.","insight":"Slow moves one step, fast two; they meet iff a cycle exists.","brute":"O(n), O(n) set.","opt":"O(n), O(1).","pitfalls":"Fast needs two safe next checks.","code":"def has_cycle(head) -> bool:\n    slow=fast=head\n    while fast and fast.next:\n        slow=slow.next;fast=fast.next.next\n        if slow is fast:return True\n    return False"},{"id":143,"title":"Reorder List","difficulty":"Medium","pattern":"Linked List Composition","trigger":"Reorder L0→L1→... into L0→Ln→L1→Ln-1→....","anti":"Array conversion uses O(n) extra.","insight":"Split at middle, reverse second half, merge alternately.","brute":"O(n), O(n) array.","opt":"O(n), O(1) extra.","pitfalls":"Cut the first half before reversing; merge until second half is exhausted.","code":"def reorder_list(head) -> None:\n    if not head or not head.next:return\n    slow=fast=head\n    while fast.next and fast.next.next:slow=slow.next;fast=fast.next.next\n    second=slow.next;slow.next=None\n    prev=None\n    while second:\n        nxt=second.next;second.next=prev;prev=second;second=nxt\n    a,b=head,prev\n    while b:\n        an,bn=a.next,b.next\n        a.next=b;b.next=an;a,b=an,bn"},{"id":146,"title":"LRU Cache","difficulty":"Medium","pattern":"Hash Map + Doubly Linked List","trigger":"Support get/put with O(1) average lookup and eviction by least-recent use.","anti":"A list gives O(1) insertion but O(n) lookup; a map alone lacks O(1) recency ordering.","insight":"Hash map finds nodes; doubly linked list maintains recency order.","brute":"O(n) per operation with a list.","opt":"O(1) average get/put; O(capacity) space.","pitfalls":"Remove and reinsert nodes on every access; use dummy head/tail to simplify links.","code":"class LRUCache:\n    def __init__(self, capacity: int):\n        self.cap=capacity;self.mp={}\n        self.head=self.Node(0,0);self.tail=self.Node(0,0)\n        self.head.next=self.tail;self.tail.prev=self.head\n    class Node:\n        def __init__(self,k,v):self.key=k;self.val=v;self.prev=self.next=None\n    def remove(self,n):\n        n.prev.next=n.next;n.next.prev=n.prev\n    def add_front(self,n):\n        n.next=self.head.next;n.prev=self.head\n        self.head.next.prev=n;self.head.next=n\n    def get(self,key):\n        if key not in self.mp:return -1\n        n=self.mp[key];self.remove(n);self.add_front(n);return n.val\n    def put(self,key,value):\n        if key in self.mp:self.remove(self.mp[key])\n        n=self.Node(key,value);self.mp[key]=n;self.add_front(n)\n        if len(self.mp)>self.cap:\n            old=self.tail.prev;self.remove(old);del self.mp[old.key]"},{"id":152,"title":"Maximum Product Subarray","difficulty":"Medium","pattern":"Dynamic Programming","trigger":"Find the contiguous subarray with maximum product, including negative values.","anti":"Enumerating all subarrays is O(n²).","insight":"Track both maximum and minimum product ending here because a negative can swap them.","brute":"O(n²), O(1).","opt":"O(n), O(1).","pitfalls":"Zero resets the running product; swap max/min when current value is negative.","code":"def max_product(nums: list[int]) -> int:\n    hi=lo=ans=nums[0]\n    for x in nums[1:]:\n        if x<0:hi,lo=lo,hi\n        hi=max(x,hi*x);lo=min(x,lo*x);ans=max(ans,hi)\n    return ans"},{"id":162,"title":"Find Peak Element","difficulty":"Medium","pattern":"Binary Search","trigger":"Find any element greater than its neighbors in O(log n).","anti":"Linear scan is O(n).","insight":"If nums[mid] < nums[mid+1], a peak exists to the right; otherwise one exists at/before mid.","brute":"O(n), O(1).","opt":"O(log n), O(1).","pitfalls":"Use a consistent half-open/closed interval; boundary elements count as peaks.","code":"def find_peak(nums: list[int]) -> int:\n    l,r=0,len(nums)-1\n    while l<r:\n        m=(l+r)//2\n        if nums[m]<nums[m+1]:l=m+1\n        else:r=m\n    return l"},{"id":167,"title":"Two Sum II - Input Array Is Sorted","difficulty":"Medium","pattern":"Two Pointers","trigger":"Sorted array + target pair.","anti":"Hash map is O(n) space and ignores sortedness.","insight":"Move left/right based on whether their sum is below/above target.","brute":"O(n), O(n) hash map.","opt":"O(n), O(1).","pitfalls":"Use 1-based output if required by the problem.","code":"def two_sum_sorted(numbers: list[int], target: int) -> list[int]:\n    l,r=0,len(numbers)-1\n    while l<r:\n        s=numbers[l]+numbers[r]\n        if s==target:return [l+1,r+1]\n        if s<target:l+=1\n        else:r-=1\n    return []"},{"id":169,"title":"Majority Element","difficulty":"Easy","pattern":"Boyer-Moore","trigger":"Find an element occurring more than n/2 times.","anti":"Counting with a map uses O(n) space.","insight":"A majority cancels all non-majority elements; maintain candidate and vote count.","brute":"O(n), O(n) map.","opt":"O(n), O(1).","pitfalls":"Boyer-Moore requires the guaranteed majority condition.","code":"def majority_element(nums: list[int]) -> int:\n    cand,count=None,0\n    for x in nums:\n        if count==0:cand=x\n        count += 1 if x==cand else -1\n    return cand"},{"id":175,"title":"Combine Two Tables","difficulty":"Easy","pattern":"SQL","trigger":"Join rows from two tables by a shared key.","anti":"Nested-loop matching is conceptually O(nm).","insight":"Use an SQL JOIN on the key.","brute":"O(nm) conceptual nested matching.","opt":"Database optimizer chooses an efficient join; logical query is a JOIN.","pitfalls":"Use aliases and preserve the requested columns/rows.","code":"SELECT p.firstName, p.lastName, a.city, a.state\nFROM Person p\nLEFT JOIN Address a ON p.personId = a.personId;"},{"id":181,"title":"Employees Earning More Than Their Managers","difficulty":"Easy","pattern":"SQL","trigger":"Compare each employee's salary with their manager's salary.","anti":"Application-side row matching is unnecessary.","insight":"Self-join Employee to itself: employee row joins manager row by managerId.","brute":"O(n²) conceptual comparison.","opt":"Efficient indexed/join execution; logical complexity depends on DB plan.","pitfalls":"Join employee.managerId to manager.id, not employee.id.","code":"SELECT e.name AS Employee\nFROM Employee e\nJOIN Employee m ON e.managerId = m.id\nWHERE e.salary > m.salary;"},{"id":189,"title":"Rotate Array","difficulty":"Medium","pattern":"Array / Reversal","trigger":"Rotate an array in-place by k positions.","anti":"Repeated one-step rotations can be O(nk).","insight":"Reverse all, reverse first k, reverse the remainder.","brute":"O(nk), O(1).","opt":"O(n), O(1).","pitfalls":"Normalize k modulo n; use the correct reversal order.","code":"def rotate(nums: list[int], k: int) -> None:\n    n=len(nums); k%=n\n    def rev(l,r):\n        while l<r: nums[l],nums[r]=nums[r],nums[l];l+=1;r-=1\n    rev(0,n-1);rev(0,k-1);rev(k,n-1)"},{"id":198,"title":"House Robber","difficulty":"Medium","pattern":"Dynamic Programming","trigger":"Maximize money when adjacent houses cannot both be robbed.","anti":"Enumerating rob/not-rob choices is exponential.","insight":"At each house choose skip previous best or rob current + best from two houses back.","brute":"O(2^n) recursion.","opt":"O(n), O(1) space.","pitfalls":"Base state must support an empty prefix.","code":"def rob(nums: list[int]) -> int:\n    prev2=prev1=0\n    for x in nums:\n        prev2,prev1=prev1,max(prev1,prev2+x)\n    return prev1"},{"id":199,"title":"Binary Tree Right Side View","difficulty":"Medium","pattern":"Tree BFS","trigger":"Return the last visible node at each depth from the right.","anti":"DFS can work but requires tracking maximum depth.","insight":"BFS processes each level; the last node in that level is visible.","brute":"O(n), O(n).","opt":"O(n), O(w).","pitfalls":"Use level boundaries; rightmost can also be obtained by right-first DFS.","code":"from collections import deque\ndef right_side_view(root):\n    if not root:return []\n    q=deque([root]);out=[]\n    while q:\n        for i in range(len(q)):\n            node=q.popleft()\n            if i==0: pass\n            if node.left:q.append(node.left)\n            if node.right:q.append(node.right)\n            if i==0: last=node\n        out.append(last.val)\n    return out"},{"id":200,"title":"Number of Islands","difficulty":"Medium","pattern":"Grid DFS/BFS","trigger":"Count connected groups of land cells in a grid.","anti":"Checking each land cell without marking causes repeated traversal.","insight":"DFS/BFS flood-fills each island once and marks visited cells.","brute":"O(mn) with repeated rescans; can degrade.","opt":"O(mn) time, O(mn) worst-case recursion/queue.","pitfalls":"Mark visited when entering; use four directions.","code":"def num_islands(grid: list[list[str]]) -> int:\n    m,n=len(grid),len(grid[0]);ans=0\n    def dfs(r,c):\n        if r<0 or r>=m or c<0 or c>=n or grid[r][c]!='1':return\n        grid[r][c]='0'\n        dfs(r+1,c);dfs(r-1,c);dfs(r,c+1);dfs(r,c-1)\n    for r in range(m):\n        for c in range(n):\n            if grid[r][c]=='1':ans+=1;dfs(r,c)\n    return ans"},{"id":202,"title":"Happy Number","difficulty":"Easy","pattern":"Cycle Detection","trigger":"Repeatedly replace a number with the sum of squares of digits; determine if it reaches 1.","anti":"A set is straightforward but uses O(n) space.","insight":"The sequence enters a cycle; Floyd cycle detection gives O(1) space.","brute":"O(n) time, O(n) set.","opt":"O(log n) per transformation; O(1) extra with cycle detection.","pitfalls":"Do not assume every non-1 value decreases monotonically.","code":"def is_happy(n: int) -> bool:\n    def nxt(x):\n        total=0\n        while x:x,d=divmod(x,10);total+=d*d\n        return total\n    slow=fast=n\n    while True:\n        slow=nxt(slow);fast=nxt(nxt(fast))\n        if fast==1:return True\n        if slow==fast:return False"},{"id":204,"title":"Count Primes","difficulty":"Medium","pattern":"Sieve of Eratosthenes","trigger":"Count primes below n.","anti":"Testing every number by trial division is O(n√n).","insight":"Mark multiples of each prime starting at p².","brute":"O(n√n).","opt":"O(n log log n) time, O(n) space.","pitfalls":"Range is [2,n); only sieve p up to √n.","code":"def count_primes(n: int) -> int:\n    if n<=2:return 0\n    prime=[True]*n;prime[0]=prime[1]=False\n    p=2\n    while p*p<n:\n        if prime[p]:prime[p*p:n:p]=[False]*(((n-1-p*p)//p)+1)\n        p+=1\n    return sum(prime)"},{"id":206,"title":"Reverse Linked List","difficulty":"Easy","pattern":"Linked List Reversal","trigger":"Reverse next pointers in a singly linked list.","anti":"Copying nodes uses extra memory.","insight":"Maintain prev/current/next and reverse one pointer at a time.","brute":"O(n), O(n) copied nodes.","opt":"O(n), O(1).","pitfalls":"Save next before overwriting current.next.","code":"def reverse_list(head):\n    prev=None;cur=head\n    while cur:\n        nxt=cur.next;cur.next=prev;prev=cur;cur=nxt\n    return prev"},{"id":207,"title":"Course Schedule","difficulty":"Medium","pattern":"Topological Sort","trigger":"Determine whether prerequisites contain a cycle.","anti":"DFS without explicit cycle state is easy to get wrong.","insight":"Build indegrees and repeatedly remove zero-indegree courses.","brute":"O(V+E) DFS.","opt":"O(V+E) time, O(V+E) graph space.","pitfalls":"A valid schedule exists iff all V nodes are processed.","code":"from collections import deque\ndef can_finish(num_courses: int, prerequisites: list[list[int]]) -> bool:\n    g=[[] for _ in range(num_courses)];ind=[0]*num_courses\n    for a,b in prerequisites:g[b].append(a);ind[a]+=1\n    q=deque(i for i,x in enumerate(ind) if x==0);seen=0\n    while q:\n        u=q.popleft();seen+=1\n        for v in g[u]:\n            ind[v]-=1\n            if ind[v]==0:q.append(v)\n    return seen==num_courses"},{"id":209,"title":"Minimum Size Subarray Sum","difficulty":"Medium","pattern":"Sliding Window","trigger":"Positive numbers + minimum length subarray reaching at least target.","anti":"Prefix-sum + binary search is possible but more complex; brute-force is O(n²).","insight":"Because values are positive, increasing right increases sum and moving left decreases it.","brute":"O(n²), O(1).","opt":"O(n), O(1).","pitfalls":"Positivity is the key anti-trigger: with negative values, this simple window is invalid.","code":"def min_sub_array_len(target: int, nums: list[int]) -> int:\n    l=0;s=0;ans=float('inf')\n    for r,x in enumerate(nums):\n        s+=x\n        while s>=target:\n            ans=min(ans,r-l+1);s-=nums[l];l+=1\n    return 0 if ans==float('inf') else ans"},{"id":210,"title":"Course Schedule II","difficulty":"Medium","pattern":"Topological Sort","trigger":"Return a valid course ordering or [] when dependencies cycle.","anti":"Trying permutations is factorial.","insight":"Kahn's algorithm outputs nodes as their indegree becomes zero.","brute":"O(V!), conceptually.","opt":"O(V+E) time, O(V+E) space.","pitfalls":"Reverse edge direction consistently; result length must equal number of courses.","code":"from collections import deque\ndef find_order(num_courses: int, prerequisites: list[list[int]]) -> list[int]:\n    g=[[] for _ in range(num_courses)];ind=[0]*num_courses\n    for a,b in prerequisites:g[b].append(a);ind[a]+=1\n    q=deque(i for i in range(num_courses) if ind[i]==0);out=[]\n    while q:\n        u=q.popleft();out.append(u)\n        for v in g[u]:\n            ind[v]-=1\n            if ind[v]==0:q.append(v)\n    return out if len(out)==num_courses else []"},{"id":215,"title":"Kth Largest Element in an Array","difficulty":"Medium","pattern":"Heap / Quickselect","trigger":"Find kth largest without fully sorting when O(n log k) or average O(n) is preferred.","anti":"Sorting is O(n log n).","insight":"Maintain a min-heap of size k; its root is kth largest.","brute":"O(n log n), O(1) extra sort.","opt":"O(n log k), O(k).","pitfalls":"For kth largest, use a min-heap of k elements.","code":"import heapq\ndef find_kth_largest(nums: list[int], k: int) -> int:\n    h=[]\n    for x in nums:\n        heapq.heappush(h,x)\n        if len(h)>k:heapq.heappop(h)\n    return h[0]"},{"id":217,"title":"Contains Duplicate","difficulty":"Easy","pattern":"Hash Set","trigger":"Determine whether any value appears more than once.","anti":"Sorting is O(n log n).","insight":"A set detects membership in O(1) average time.","brute":"O(n log n) sort.","opt":"O(n) average, O(n) space.","pitfalls":"Set size comparison is enough; duplicates need not be located.","code":"def contains_duplicate(nums: list[int]) -> bool:\n    return len(nums)!=len(set(nums))"},{"id":219,"title":"Contains Duplicate II","difficulty":"Easy","pattern":"Hash Map / Sliding Window","trigger":"Detect duplicate values whose indices differ by at most k.","anti":"Checking all nearby pairs can be O(nk).","insight":"Keep the most recent index for each value.","brute":"O(nk), O(n).","opt":"O(n), O(n).","pitfalls":"Update the stored index after checking the distance.","code":"def contains_nearby_duplicate(nums: list[int], k: int) -> bool:\n    last={}\n    for i,x in enumerate(nums):\n        if x in last and i-last[x]<=k:return True\n        last[x]=i\n    return False"},{"id":231,"title":"Power of Two","difficulty":"Easy","pattern":"Bit Manipulation","trigger":"Determine whether a positive integer is an exact power of two.","anti":"Repeated division is O(log n).","insight":"A power of two has exactly one set bit, so n & (n-1) == 0.","brute":"O(log n), O(1).","opt":"O(1), O(1).","pitfalls":"Require n > 0.","code":"def is_power_of_two(n: int) -> bool:\n    return n>0 and n&(n-1)==0"},{"id":234,"title":"Palindrome Linked List","difficulty":"Easy","pattern":"Fast/Slow + Reverse","trigger":"Check linked-list values for palindrome symmetry in O(1) extra space.","anti":"Copying values to an array uses O(n).","insight":"Find middle, reverse second half, compare halves.","brute":"O(n), O(n).","opt":"O(n), O(1) extra.","pitfalls":"Odd/even length handling; optionally restore the list after comparison.","code":"def is_palindrome_list(head) -> bool:\n    slow=fast=head\n    while fast and fast.next:slow=slow.next;fast=fast.next.next\n    prev=None\n    while slow:\n        nxt=slow.next;slow.next=prev;prev=slow;slow=nxt\n    a,b=head,prev\n    while b:\n        if a.val!=b.val:return False\n        a=a.next;b=b.next\n    return True"},{"id":236,"title":"Lowest Common Ancestor of a Binary Tree","difficulty":"Medium","pattern":"Tree DFS","trigger":"Find the deepest node that is an ancestor of both target nodes.","anti":"Parent-map plus ancestor sets uses O(n) memory.","insight":"Recursive DFS returns a target or the LCA found in a subtree.","brute":"O(n), O(n) parent map.","opt":"O(n), O(h) recursion.","pitfalls":"If current node is p or q, return it; if both sides return non-null, current is LCA.","code":"def lowest_common_ancestor(root, p, q):\n    if not root or root is p or root is q:return root\n    left=lowest_common_ancestor(root.left,p,q);right=lowest_common_ancestor(root.right,p,q)\n    return root if left and right else left or right"},{"id":238,"title":"Product of Array Except Self","difficulty":"Medium","pattern":"Prefix / Suffix","trigger":"Return product of all values except self without division.","anti":"For each position multiplying all other values is O(n²).","insight":"Store prefix products in output, then multiply by a running suffix.","brute":"O(n²), O(1).","opt":"O(n), O(1) extra beyond output.","pitfalls":"Zeros are naturally handled; do not use division if prohibited.","code":"def product_except_self(nums: list[int]) -> list[int]:\n    out=[1]*len(nums);p=1\n    for i,x in enumerate(nums):out[i]=p;p*=x\n    p=1\n    for i in range(len(nums)-1,-1,-1):out[i]*=p;p*=nums[i]\n    return out"},{"id":239,"title":"Sliding Window Maximum","difficulty":"Hard","pattern":"Monotonic Deque","trigger":"Find maximum in every fixed-size sliding window.","anti":"Scanning each window is O(nk).","insight":"Maintain a decreasing deque of candidate indices.","brute":"O(nk), O(1).","opt":"O(n), O(k).","pitfalls":"Remove expired indices from front; remove smaller values from back.","code":"from collections import deque\ndef max_sliding_window(nums: list[int], k: int) -> list[int]:\n    q=deque();out=[]\n    for i,x in enumerate(nums):\n        while q and q[0]<=i-k:q.popleft()\n        while q and nums[q[-1]]<=x:q.pop()\n        q.append(i)\n        if i>=k-1:out.append(nums[q[0]])\n    return out"},{"id":242,"title":"Valid Anagram","difficulty":"Easy","pattern":"Hash Map / Count","trigger":"Determine whether two strings contain the same character frequencies.","anti":"Sorting is O(n log n).","insight":"Count characters and compare frequency maps.","brute":"O(n log n) sorting.","opt":"O(n), O(k) map.","pitfalls":"Length mismatch immediately fails; counts must include multiplicity.","code":"from collections import Counter\ndef is_anagram(s: str, t: str) -> bool:\n    return Counter(s)==Counter(t)"},{"id":253,"title":"Meeting Rooms II","difficulty":"Medium","pattern":"Intervals / Sweep","trigger":"Find the minimum number of rooms needed for overlapping meetings.","anti":"Comparing every meeting with every other is O(n²).","insight":"Sort starts and ends separately and sweep both pointers.","brute":"O(n²).","opt":"O(n log n), O(n).","pitfalls":"When a start equals an end, decide whether the meeting ending frees a room first according to interval semantics.","code":"def min_meeting_rooms(intervals: list[list[int]]) -> int:\n    starts=sorted(x[0] for x in intervals);ends=sorted(x[1] for x in intervals)\n    s=e=rooms=ans=0\n    while s<len(intervals):\n        if starts[s]<ends[e]:\n            rooms+=1;ans=max(ans,rooms);s+=1\n        else:\n            rooms-=1;e+=1\n    return ans"},{"id":268,"title":"Missing Number","difficulty":"Easy","pattern":"Math / XOR","trigger":"Find the missing value from 0..n.","anti":"A set uses O(n) space; sorting is O(n log n).","insight":"XOR all indices and values; pairs cancel leaving the missing number.","brute":"O(n log n) sorting or O(n) set.","opt":"O(n), O(1).","pitfalls":"Include n in the XOR range.","code":"def missing_number(nums: list[int]) -> int:\n    x=len(nums)\n    for i,v in enumerate(nums):x^=i^v\n    return x"},{"id":283,"title":"Move Zeroes","difficulty":"Easy","pattern":"Two Pointers","trigger":"Move all zeros to the end while preserving nonzero order in-place.","anti":"Filtering into a new list uses extra memory.","insight":"Write nonzeros forward, then fill the remainder with zeros.","brute":"O(n), O(n).","opt":"O(n), O(1).","pitfalls":"Stable order matters.","code":"def move_zeroes(nums: list[int]) -> None:\n    w=0\n    for x in nums:\n        if x!=0:nums[w]=x;w+=1\n    for i in range(w,len(nums)):nums[i]=0"},{"id":287,"title":"Find the Duplicate Number","difficulty":"Medium","pattern":"Cycle Detection","trigger":"Array values form a linked-list-like functional graph with one duplicate.","anti":"A set is O(n) space; sorting modifies data.","insight":"Treat nums[i] as the next pointer and find the cycle entrance with Floyd.","brute":"O(n), O(n) set.","opt":"O(n), O(1).","pitfalls":"Do not modify the array; Floyd phase 2 is required to find the duplicate value.","code":"def find_duplicate(nums: list[int]) -> int:\n    slow=fast=nums[0]\n    while True:\n        slow=nums[slow];fast=nums[nums[fast]]\n        if slow==fast:break\n    slow=nums[0]\n    while slow!=fast:\n        slow=nums[slow];fast=nums[fast]\n    return slow"},{"id":295,"title":"Find Median from Data Stream","difficulty":"Hard","pattern":"Two Heaps","trigger":"Maintain a median as numbers arrive online.","anti":"Sorting all values after every insertion is O(n log n) per insert.","insight":"Max-heap stores lower half; min-heap stores upper half; keep sizes balanced.","brute":"O(n log n) per insertion if re-sorting.","opt":"O(log n) insertion, O(1) median; O(n) space.","pitfalls":"Python heapq is min-only, so negate lower-half values.","code":"import heapq\nclass MedianFinder:\n    def __init__(self):\n        self.lo=[];self.hi=[]\n    def add_num(self,num:int)->None:\n        heapq.heappush(self.lo,-num)\n        if self.hi and -self.lo[0]>self.hi[0]:\n            x=-heapq.heappop(self.lo);heapq.heappush(self.hi,x)\n        if len(self.lo)>len(self.hi)+1:\n            heapq.heappush(self.hi,-heapq.heappop(self.lo))\n        if len(self.hi)>len(self.lo):\n            heapq.heappush(self.lo,-heapq.heappop(self.hi))\n    def find_median(self)->float:\n        if len(self.lo)>len(self.hi):return -self.lo[0]\n        return (-self.lo[0]+self.hi[0])/2"},{"id":314,"title":"Binary Tree Vertical Order Traversal","difficulty":"Medium","pattern":"Tree BFS + Coordinates","trigger":"Group tree nodes by horizontal column, top-to-bottom and left-to-right.","anti":"A DFS with sorting collected nodes is O(n log n).","insight":"BFS naturally preserves top-to-bottom order while tracking column indices.","brute":"O(n log n), O(n).","opt":"O(n) traversal plus column sorting O(c log c).","pitfalls":"Column order is left to right; same-row order is BFS order.","code":"from collections import defaultdict,deque\ndef vertical_order(root):\n    if not root:return []\n    cols=defaultdict(list);q=deque([(root,0)]);lo=hi=0\n    while q:\n        node,c=q.popleft();cols[c].append(node.val);lo=min(lo,c);hi=max(hi,c)\n        if node.left:q.append((node.left,c-1))\n        if node.right:q.append((node.right,c+1))\n    return [cols[c] for c in range(lo,hi+1)]"},{"id":322,"title":"Coin Change","difficulty":"Medium","pattern":"Dynamic Programming","trigger":"Find minimum number of coins needed to make an amount.","anti":"Recursive enumeration is exponential.","insight":"dp[a] = minimum coins for amount a; try every coin.","brute":"Exponential recursion.","opt":"O(amount·coins), O(amount).","pitfalls":"Initialize unreachable states to infinity; dp[0]=0.","code":"def coin_change(coins: list[int], amount: int) -> int:\n    dp=[amount+1]*(amount+1);dp[0]=0\n    for a in range(1,amount+1):\n        for c in coins:\n            if c<=a:dp[a]=min(dp[a],dp[a-c]+1)\n    return -1 if dp[amount]>amount else dp[amount]"},{"id":339,"title":"Nested List Weight Sum","difficulty":"Medium","pattern":"DFS / BFS","trigger":"Sum nested integers weighted by their depth.","anti":"Flattening loses depth information unless stored separately.","insight":"DFS carries current depth and adds value*depth.","brute":"O(n) time, O(n) flattening.","opt":"O(n) time, O(h) recursion.","pitfalls":"Depth starts at the problem-defined level, usually 1.","code":"def depth_sum(nested_list) -> int:\n    def dfs(items,depth):\n        total=0\n        for x in items:\n            if x.isInteger():total+=x.getInteger()*depth\n            else:total+=dfs(x.getList(),depth+1)\n        return total\n    return dfs(nested_list,1)"},{"id":343,"title":"Integer Break","difficulty":"Medium","pattern":"Dynamic Programming","trigger":"Break n into at least two positive integers maximizing their product.","anti":"Enumerating all partitions is exponential.","insight":"dp[n] is max product; choose first piece i and either stop or use dp[n-i].","brute":"Exponential partition enumeration.","opt":"O(n²), O(n).","pitfalls":"For small n, handle n=2/3 naturally through initialization.","code":"def integer_break(n: int) -> int:\n    dp=[0]*(n+1);dp[1]=1\n    for x in range(2,n+1):\n        for i in range(1,x):\n            dp[x]=max(dp[x],i*(x-i),i*dp[x-i])\n    return dp[n]"},{"id":344,"title":"Reverse String","difficulty":"Easy","pattern":"Two Pointers","trigger":"Reverse a character array in-place.","anti":"Creating a reversed copy uses O(n) extra.","insight":"Swap symmetric positions.","brute":"O(n), O(n).","opt":"O(n), O(1).","pitfalls":"Operate on the provided mutable list.","code":"def reverse_string(s: list[str]) -> None:\n    l,r=0,len(s)-1\n    while l<r:s[l],s[r]=s[r],s[l];l+=1;r-=1"},{"id":347,"title":"Top K Frequent Elements","difficulty":"Medium","pattern":"Hash Map + Heap","trigger":"Return the k most frequent values.","anti":"Sorting all frequencies is O(n log n).","insight":"Count frequencies, then keep a size-k min-heap.","brute":"O(n log n).","opt":"O(n log k), O(n).","pitfalls":"Heap stores (frequency,value); final order may be unspecified.","code":"from collections import Counter\nimport heapq\ndef top_k_frequent(nums: list[int], k: int) -> list[int]:\n    return [x for _,x in heapq.nsmallest(k,[(-f,x) for x,f in Counter(nums).items()])]"},{"id":349,"title":"Intersection of Two Arrays","difficulty":"Easy","pattern":"Hash Set","trigger":"Return distinct values common to two arrays.","anti":"Nested membership checks are O(nm).","insight":"Convert one or both arrays to sets.","brute":"O(nm).","opt":"O(n+m) average, O(n+m) space.","pitfalls":"Result is unique; do not return duplicates.","code":"def intersection(nums1: list[int], nums2: list[int]) -> list[int]:\n    return list(set(nums1)&set(nums2))"},{"id":394,"title":"Decode String","difficulty":"Medium","pattern":"Stack","trigger":"Decode nested k[encoded] expressions.","anti":"Recursive string slicing can repeatedly copy large strings.","insight":"Stack stores prior string and repeat count when entering brackets.","brute":"Potentially O(output²) with repeated concatenation.","opt":"O(output), plus O(depth) state.","pitfalls":"Parse multi-digit counts; append decoded segment after closing bracket.","code":"def decode_string(s: str) -> str:\n    stack=[];cur=\"\";num=0\n    for ch in s:\n        if ch.isdigit():num=num*10+int(ch)\n        elif ch=='[':stack.append((cur,num));cur=\"\";num=0\n        elif ch==']':\n            prev,k=stack.pop();cur=prev+cur*k\n        else:cur+=ch\n    return cur"},{"id":408,"title":"Valid Word Abbreviation","difficulty":"Easy","pattern":"Two Pointers / Parsing","trigger":"Check whether digits in an abbreviation represent skipped characters.","anti":"Generating every expansion is unnecessary.","insight":"Scan word and abbreviation together; parse multi-digit skip counts.","brute":"O(nm) expansion.","opt":"O(n+m), O(1).","pitfalls":"Leading zero in a numeric abbreviation is invalid.","code":"def valid_word_abbreviation(word: str, abbr: str) -> bool:\n    i=j=0\n    while j<len(abbr):\n        if abbr[j].isalpha():\n            if i>=len(word) or word[i]!=abbr[j]:return False\n            i+=1;j+=1\n        else:\n            if abbr[j]=='0':return False\n            num=0\n            while j<len(abbr) and abbr[j].isdigit():\n                num=num*10+int(abbr[j]);j+=1\n            i+=num\n    return i==len(word)"},{"id":410,"title":"Split Array Largest Sum","difficulty":"Hard","pattern":"Binary Search on Answer","trigger":"Split an array into at most k parts minimizing the largest part sum.","anti":"Enumerating all partitions is exponential.","insight":"Binary-search the maximum allowed subarray sum and greedily count required pieces.","brute":"Exponential partitioning.","opt":"O(n log(sum(nums))), O(1) extra.","pitfalls":"Feasibility is monotonic: larger allowed sum never needs more pieces.","code":"def split_array(nums: list[int], k: int) -> int:\n    def feasible(limit):\n        parts=1;total=0\n        for x in nums:\n            if total+x>limit:parts+=1;total=x\n            else:total+=x\n        return parts<=k\n    l,r=max(nums),sum(nums)\n    while l<r:\n        m=(l+r)//2\n        if feasible(m):r=m\n        else:l=m+1\n    return l"},{"id":424,"title":"Longest Repeating Character Replacement","difficulty":"Medium","pattern":"Sliding Window","trigger":"Longest substring that can become one repeated character with at most k replacements.","anti":"Checking each substring's frequency is O(n²).","insight":"A window is valid when window_size - max_frequency <= k.","brute":"O(n²).","opt":"O(n), O(Alphabet).","pitfalls":"max_frequency can remain stale; it is safe for maximizing the window.","code":"from collections import defaultdict\ndef character_replacement(s: str, k: int) -> int:\n    count=defaultdict(int);l=0;mx=ans=0\n    for r,ch in enumerate(s):\n        count[ch]+=1;mx=max(mx,count[ch])\n        while r-l+1-mx>k:\n            count[s[l]]-=1;l+=1\n        ans=max(ans,r-l+1)\n    return ans"},{"id":485,"title":"Max Consecutive Ones","difficulty":"Easy","pattern":"Sliding Window","trigger":"Find the longest contiguous run of ones.","anti":"Simple counting works; a window is useful for the family connection.","insight":"Track a start boundary whenever a zero appears.","brute":"O(n), O(1).","opt":"O(n), O(1).","pitfalls":"Reset count on zero or maintain last zero.","code":"def find_max_consecutive_ones(nums: list[int]) -> int:\n    ans=cur=0\n    for x in nums:\n        cur=cur+1 if x==1 else 0\n        ans=max(ans,cur)\n    return ans"},{"id":496,"title":"Next Greater Element I","difficulty":"Easy","pattern":"Monotonic Stack","trigger":"Find the next greater value to the right for each queried value.","anti":"Scanning right for every element is O(n²).","insight":"A decreasing stack resolves elements when a larger value arrives.","brute":"O(n²).","opt":"O(n), O(n).","pitfalls":"Map values to answers only when values are unique as specified.","code":"def next_greater_element(nums1: list[int], nums2: list[int]) -> list[int]:\n    stack=[];mp={}\n    for x in nums2:\n        while stack and stack[-1]<x:mp[stack.pop()]=x\n        stack.append(x)\n    return [mp.get(x,-1) for x in nums1]"},{"id":503,"title":"Next Greater Element II","difficulty":"Medium","pattern":"Monotonic Stack","trigger":"Next greater may wrap around to the beginning of a circular array.","anti":"Naively scanning circularly is O(n²).","insight":"Traverse indices twice while keeping a decreasing stack.","brute":"O(n²).","opt":"O(n), O(n).","pitfalls":"Only push real indices during the first pass or use i%n consistently.","code":"def next_greater_circular(nums: list[int]) -> list[int]:\n    n=len(nums);ans=[-1]*n;stack=[]\n    for i in range(2*n):\n        x=nums[i%n]\n        while stack and nums[stack[-1]]<x:ans[stack.pop()]=x\n        if i<n:stack.append(i)\n    return ans"},{"id":509,"title":"Fibonacci Number","difficulty":"Easy","pattern":"Dynamic Programming","trigger":"Compute Fibonacci without exponential recursion.","anti":"Naive recursion is O(2^n).","insight":"Keep only the previous two values.","brute":"O(2^n), O(n) recursion.","opt":"O(n), O(1).","pitfalls":"Define F(0), F(1) correctly.","code":"def fib(n: int) -> int:\n    a,b=0,1\n    for _ in range(n):a,b=b,a+b\n    return a"},{"id":528,"title":"Random Pick with Weight","difficulty":"Medium","pattern":"Prefix Sum + Binary Search","trigger":"Sample an index with probability proportional to its weight.","anti":"Expanding each weight into repeated entries uses O(sum(weights)) space.","insight":"Build cumulative weights and binary-search a random point.","brute":"O(sum(weights)) expansion.","opt":"O(n) preprocessing, O(log n) per pick, O(n) space.","pitfalls":"Random target is in [1,total]; use first prefix >= target.","code":"import random,bisect\nclass WeightedPicker:\n    def __init__(self,w:list[int]):\n        self.pref=[];s=0\n        for x in w:s+=x;self.pref.append(s)\n        self.total=s\n    def pick_index(self)->int:\n        return bisect.bisect_left(self.pref,random.randint(1,self.total))"},{"id":540,"title":"Single Element in a Sorted Array","difficulty":"Medium","pattern":"Binary Search","trigger":"Sorted array has pairs except one singleton; find it in O(log n).","anti":"XOR finds the singleton but ignores the intended sorted/logarithmic structure.","insight":"Before the singleton, pairs start at even indices; after it, pairing shifts.","brute":"O(n), O(1) XOR.","opt":"O(log n), O(1).","pitfalls":"Force mid to even and compare nums[mid] with nums[mid+1].","code":"def single_non_duplicate(nums: list[int]) -> int:\n    l,r=0,len(nums)-1\n    while l<r:\n        m=(l+r)//2;m-=m&1\n        if nums[m]==nums[m+1]:l=m+2\n        else:r=m\n    return nums[l]"},{"id":543,"title":"Diameter of Binary Tree","difficulty":"Easy","pattern":"Special / Misc","trigger":"Use the wording and constraints to identify the dominant data structure or invariant.","anti":"Do not force a memorized pattern when the constraints point to a simpler direct solution.","insight":"Start with the smallest state that captures what the prompt asks you to preserve.","brute":"Usually brute force follows directly from the definition; complexity depends on the problem.","opt":"Choose the lowest-complexity approach justified by the stated constraints.","pitfalls":"Check empty input, boundary indices, duplicate values, and output format.","code":"# Implement the problem directly from its stated invariant.\n# Replace this placeholder with the exact interview implementation."},{"id":560,"title":"Subarray Sum Equals K","difficulty":"Medium","pattern":"Prefix Sum + Hash Map","trigger":"Count contiguous subarrays whose sum equals k, including negative numbers.","anti":"Two pointers fails with negative values; brute-force is O(n²).","insight":"If current prefix is P, an earlier prefix P-k defines a subarray summing k.","brute":"O(n²), O(1).","opt":"O(n), O(n).","pitfalls":"Initialize prefix frequency {0:1}; add count before incrementing current prefix frequency.","code":"def subarray_sum(nums: list[int], k: int) -> int:\n    freq={0:1};p=ans=0\n    for x in nums:\n        p+=x;ans+=freq.get(p-k,0);freq[p]=freq.get(p,0)+1\n    return ans"},{"id":621,"title":"Task Scheduler","difficulty":"Medium","pattern":"Greedy / Heap","trigger":"Schedule tasks with cooldown n while minimizing total intervals.","anti":"Naive simulation may make poor choices and be slow.","insight":"The most frequent task determines the minimum frame size; a heap simulation is a general implementation.","brute":"Naive scheduling can be much larger than needed.","opt":"O(T log 26) with heap simulation; O(26) space.","pitfalls":"Cooldown means the same task cannot reappear until n intervals have passed.","code":"import heapq\nfrom collections import Counter,deque\ndef least_interval(tasks:list[str], n:int)->int:\n    h=[-v for v in Counter(tasks).values()];heapq.heapify(h)\n    q=deque();time=0\n    while h or q:\n        time+=1\n        if h:\n            v=heapq.heappop(h)+1\n            if v:q.append((v,time+n))\n        if q and q[0][1]==time:heapq.heappush(h,q.popleft()[0])\n    return time"},{"id":647,"title":"Palindromic Substrings","difficulty":"Medium","pattern":"Expand Around Center","trigger":"Count all palindromic contiguous substrings.","anti":"Checking every substring is O(n³) if each is scanned.","insight":"Expand around every odd and even center.","brute":"O(n³) naive.","opt":"O(n²) time, O(1) extra.","pitfalls":"Count every successful expansion, not just the longest.","code":"def count_substrings(s: str) -> int:\n    ans=0\n    def expand(l,r):\n        nonlocal ans\n        while l>=0 and r<len(s) and s[l]==s[r]:\n            ans+=1;l-=1;r+=1\n    for i in range(len(s)):expand(i,i);expand(i,i+1)\n    return ans"},{"id":678,"title":"Valid Parenthesis String","difficulty":"Medium","pattern":"Greedy / Range","trigger":"Parentheses may include '*' that can act as '(', ')' or empty.","anti":"Enumerating all star assignments is exponential.","insight":"Track the range of possible open counts [low, high] while scanning.","brute":"O(2^n) assignments.","opt":"O(n), O(1).","pitfalls":"Low cannot go below zero; star can increase high and decrease low.","code":"def check_valid_string(s: str) -> bool:\n    low=high=0\n    for ch in s:\n        if ch=='(':low+=1;high+=1\n        elif ch==')':low=max(0,low-1);high-=1\n        else:low=max(0,low-1);high+=1\n        if high<0:return False\n    return low==0"},{"id":680,"title":"Valid Palindrome II","difficulty":"Easy","pattern":"Two Pointers + Greedy","trigger":"Determine whether deleting at most one character can make a palindrome.","anti":"Trying every deletion is O(n²).","insight":"On first mismatch, only deleting either mismatched endpoint can work.","brute":"O(n²).","opt":"O(n), O(1).","pitfalls":"After the first mismatch, test both possibilities; don't greedily choose one without checking.","code":"def valid_palindrome_ii(s: str) -> bool:\n    def ok(l,r):\n        while l<r:\n            if s[l]!=s[r]:return False\n            l+=1;r-=1\n        return True\n    l,r=0,len(s)-1\n    while l<r:\n        if s[l]!=s[r]:return ok(l+1,r) or ok(l,r-1)\n        l+=1;r-=1\n    return True"},{"id":704,"title":"Binary Search","difficulty":"Easy","pattern":"Binary Search","trigger":"Sorted array + exact target search.","anti":"Linear scan is O(n).","insight":"Eliminate half the search space each iteration.","brute":"O(n), O(1).","opt":"O(log n), O(1).","pitfalls":"Use a consistent closed interval and update both boundaries correctly.","code":"def binary_search(nums: list[int], target: int) -> int:\n    l,r=0,len(nums)-1\n    while l<=r:\n        m=(l+r)//2\n        if nums[m]==target:return m\n        if nums[m]<target:l=m+1\n        else:r=m-1\n    return -1"},{"id":735,"title":"Asteroid Collision","difficulty":"Medium","pattern":"Stack","trigger":"Simulate collisions where opposite-moving asteroids interact.","anti":"Repeatedly searching for collision partners can be O(n²).","insight":"Stack represents surviving asteroids; resolve only when top moves right and current moves left.","brute":"O(n²).","opt":"O(n), O(n).","pitfalls":"A collision can destroy multiple stack elements; equal magnitudes destroy both.","code":"def asteroid_collision(asteroids: list[int]) -> list[int]:\n    st=[]\n    for x in asteroids:\n        alive=True\n        while alive and x<0 and st and st[-1]>0:\n            if st[-1] < -x:st.pop()\n            elif st[-1] == -x:st.pop();alive=False\n            else:alive=False\n        if alive:st.append(x)\n    return st"},{"id":739,"title":"Daily Temperatures","difficulty":"Medium","pattern":"Monotonic Stack","trigger":"For each day, find how many days until a warmer temperature.","anti":"Scanning forward for every day is O(n²).","insight":"Keep indices with decreasing temperatures; a warmer day resolves them.","brute":"O(n²).","opt":"O(n), O(n).","pitfalls":"Store indices, not just values, because the answer is a distance.","code":"def daily_temperatures(t: list[int]) -> list[int]:\n    ans=[0]*len(t);st=[]\n    for i,x in enumerate(t):\n        while st and t[st[-1]]<x:\n            j=st.pop();ans[j]=i-j\n        st.append(i)\n    return ans"},{"id":767,"title":"Reorganize String","difficulty":"Medium","pattern":"Greedy + Heap","trigger":"Rearrange characters so no equal adjacent characters occur.","anti":"Trying all permutations is factorial.","insight":"Always place the most frequent available character, holding the previous character out of the heap.","brute":"O(n!), impossible for large n.","opt":"O(n log k), O(k).","pitfalls":"If max frequency > (n+1)/2, impossible.","code":"import heapq\nfrom collections import Counter\ndef reorganize_string(s: str) -> str:\n    h=[(-f,ch) for ch,f in Counter(s).items()];heapq.heapify(h)\n    prev=None;out=[]\n    while h:\n        f,ch=heapq.heappop(h)\n        if ch==prev:\n            if not h:return \"\"\n            f2,ch2=heapq.heappop(h);out.append(ch2);prev=ch2\n            f2+=1\n            if f2:heapq.heappush(h,(f2,ch2))\n            heapq.heappush(h,(f,ch))\n        else:\n            out.append(ch);prev=ch;f+=1\n            if f:heapq.heappush(h,(f,ch))\n    return ''.join(out)"},{"id":796,"title":"Rotate String","difficulty":"Easy","pattern":"String / Scanning","trigger":"Determine whether goal is a rotation of s.","anti":"Trying every rotation creates O(n²) work.","insight":"A string t is a rotation of s iff lengths match and t occurs in s+s.","brute":"O(n²) rotation checks.","opt":"O(n) typical substring search, O(n) space.","pitfalls":"Lengths must match before using the doubled-string test.","code":"def rotate_string(s: str, goal: str) -> bool:\n    return len(s)==len(goal) and goal in s+s"},{"id":827,"title":"Making A Large Island","difficulty":"Hard","pattern":"Grid DFS + Component Labeling","trigger":"Flip at most one 0 to maximize connected island size.","anti":"Re-running flood fill after every possible flip is O(n³) or worse.","insight":"Label each island once with an ID and size; each zero sums unique neighboring IDs.","brute":"O(n³) naive.","opt":"O(n²) time, O(n²) space.","pitfalls":"Deduplicate neighboring island IDs so one island isn't counted twice.","code":"def largest_island(grid: list[list[int]]) -> int:\n    n=len(grid);sizes={};idx=2\n    def dfs(r,c):\n        if r<0 or r>=n or c<0 or c>=n or grid[r][c]!=1:return 0\n        grid[r][c]=idx\n        return 1+dfs(r+1,c)+dfs(r-1,c)+dfs(r,c+1)+dfs(r,c-1)\n    for r in range(n):\n        for c in range(n):\n            if grid[r][c]==1:sizes[idx]=dfs(r,c);idx+=1\n    ans=max(sizes.values(),default=0)\n    for r in range(n):\n        for c in range(n):\n            if grid[r][c]==0:\n                ids={grid[nr][nc] for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)) if 0<=nr<n and 0<=nc<n and grid[nr][nc]>1}\n                ans=max(ans,1+sum(sizes[i] for i in ids))\n    return ans if ans else n*n"},{"id":863,"title":"All Nodes Distance K in Binary Tree","difficulty":"Medium","pattern":"Tree → Graph + BFS","trigger":"Find nodes exactly K edges from a target node.","anti":"Recursive distance calculations can revisit subtrees.","insight":"Add parent links so the tree becomes an undirected graph, then BFS from target.","brute":"O(n²) repeated distance search.","opt":"O(n), O(n).","pitfalls":"Visited set is essential because parent edges create cycles.","code":"from collections import deque\ndef distance_k(root,target,k):\n    parent={}\n    def link(node,p=None):\n        if not node:return\n        parent[node]=p;link(node.left,node);link(node.right,node)\n    link(root);q=deque([(target,0)]);seen={target};out=[]\n    while q:\n        node,d=q.popleft()\n        if d==k:out.append(node.val);continue\n        for nxt in (node.left,node.right,parent[node]):\n            if nxt and nxt not in seen:seen.add(nxt);q.append((nxt,d+1))\n    return out"},{"id":875,"title":"Koko Eating Bananas","difficulty":"Medium","pattern":"Binary Search on Answer","trigger":"Minimize eating speed needed to finish piles within h hours.","anti":"Trying each speed linearly is O(maxPile·n).","insight":"Binary-search speed and test whether sum(ceil(pile/speed)) <= h.","brute":"O(n·maxPile).","opt":"O(n log maxPile), O(1) extra.","pitfalls":"Search speed from 1 to max(piles); feasibility is monotonic.","code":"import math\ndef min_eating_speed(piles: list[int], h: int) -> int:\n    def ok(speed):\n        return sum((p+speed-1)//speed for p in piles)<=h\n    l,r=1,max(piles)\n    while l<r:\n        m=(l+r)//2\n        if ok(m):r=m\n        else:l=m+1\n    return l"},{"id":876,"title":"Middle of the Linked List","difficulty":"Easy","pattern":"Fast/Slow Pointers","trigger":"Find the middle node in one pass.","anti":"Counting length then walking again is two passes.","insight":"Fast moves twice as fast as slow.","brute":"O(n) time, O(1), two passes.","opt":"O(n), O(1), one pass.","pitfalls":"For even length, this returns the second middle.","code":"def middle_node(head):\n    slow=fast=head\n    while fast and fast.next:slow=slow.next;fast=fast.next.next\n    return slow"},{"id":904,"title":"Fruit Into Baskets","difficulty":"Medium","pattern":"Sliding Window","trigger":"Find longest contiguous subarray containing at most two distinct values.","anti":"Checking every subarray is O(n²).","insight":"Maintain a window with at most two distinct fruit types.","brute":"O(n²).","opt":"O(n), O(1) map because only two types remain.","pitfalls":"Shrink until distinct count <= 2.","code":"from collections import defaultdict\ndef total_fruit(fruits: list[int]) -> int:\n    count=defaultdict(int);l=ans=0\n    for r,x in enumerate(fruits):\n        count[x]+=1\n        while len(count)>2:\n            y=fruits[l];count[y]-=1\n            if count[y]==0:del count[y]\n            l+=1\n        ans=max(ans,r-l+1)\n    return ans"},{"id":938,"title":"Range Sum of BST","difficulty":"Easy","pattern":"Tree DFS / BST Pruning","trigger":"Sum BST node values within [low, high].","anti":"Visiting every node is O(n); still acceptable but ignores BST ordering.","insight":"Prune left when node.val <= low and right when node.val >= high.","brute":"O(n).","opt":"O(n) worst case, O(h) recursion; often less due to BST pruning.","pitfalls":"Use inclusive bounds exactly.","code":"def range_sum_bst(root, low: int, high: int) -> int:\n    if not root:return 0\n    if root.val<low:return range_sum_bst(root.right,low,high)\n    if root.val>high:return range_sum_bst(root.left,low,high)\n    return root.val+range_sum_bst(root.left,low,high)+range_sum_bst(root.right,low,high)"},{"id":977,"title":"Squares of a Sorted Array","difficulty":"Easy","pattern":"Two Pointers","trigger":"Square a sorted array and return sorted squares.","anti":"Squaring then sorting is O(n log n).","insight":"Largest square comes from one of the two ends; fill output from the back.","brute":"O(n log n).","opt":"O(n), O(n) output.","pitfalls":"Compare absolute values, not raw values.","code":"def sorted_squares(nums: list[int]) -> list[int]:\n    out=[0]*len(nums);l,r=0,len(nums)-1\n    for i in range(len(nums)-1,-1,-1):\n        if abs(nums[l])>abs(nums[r]):out[i]=nums[l]*nums[l];l+=1\n        else:out[i]=nums[r]*nums[r];r-=1\n    return out"},{"id":994,"title":"Rotting Oranges","difficulty":"Medium","pattern":"Multi-source BFS","trigger":"Each minute rotten oranges infect adjacent fresh oranges; find time until none remain.","anti":"Simulating minute-by-minute scans can be O(mn·minutes).","insight":"Start BFS with all rotten oranges at once; each level is one minute.","brute":"O(mn·minutes).","opt":"O(mn) time, O(mn) queue.","pitfalls":"Count fresh oranges; return -1 if any remain after BFS.","code":"from collections import deque\ndef oranges_rotting(grid: list[list[int]]) -> int:\n    m,n=len(grid),len(grid[0]);q=deque();fresh=0\n    for r in range(m):\n        for c in range(n):\n            if grid[r][c]==2:q.append((r,c,0))\n            elif grid[r][c]==1:fresh+=1\n    time=0\n    while q:\n        r,c,t=q.popleft();time=max(time,t)\n        for nr,nc in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):\n            if 0<=nr<m and 0<=nc<n and grid[nr][nc]==1:\n                grid[nr][nc]=2;fresh-=1;q.append((nr,nc,t+1))\n    return time if fresh==0 else -1"},{"id":1004,"title":"Max Consecutive Ones III","difficulty":"Medium","pattern":"Sliding Window","trigger":"Longest binary subarray after flipping at most k zeros.","anti":"Enumerating windows is O(n²).","insight":"Window is valid when number of zeros <= k.","brute":"O(n²).","opt":"O(n), O(1).","pitfalls":"Shrink only when zero count exceeds k.","code":"def longest_ones(nums: list[int], k: int) -> int:\n    l=zeros=ans=0\n    for r,x in enumerate(nums):\n        zeros+=x==0\n        while zeros>k:\n            zeros-=nums[l]==0;l+=1\n        ans=max(ans,r-l+1)\n    return ans"},{"id":1011,"title":"Capacity To Ship Packages Within D Days","difficulty":"Medium","pattern":"Binary Search on Answer","trigger":"Minimize ship capacity that delivers packages in order within D days.","anti":"Trying every capacity is O(sum(nums)·n).","insight":"Binary-search capacity and greedily count days needed.","brute":"O(n·sum(weights)).","opt":"O(n log sum(weights)), O(1).","pitfalls":"Capacity lower bound is max weight; upper bound is total weight.","code":"def ship_within_days(weights: list[int], days: int) -> int:\n    def ok(cap):\n        used=1;load=0\n        for w in weights:\n            if load+w>cap:used+=1;load=0\n            load+=w\n        return used<=days\n    l,r=max(weights),sum(weights)\n    while l<r:\n        m=(l+r)//2\n        if ok(m):r=m\n        else:l=m+1\n    return l"},{"id":1249,"title":"Minimum Remove to Make Valid Parentheses","difficulty":"Medium","pattern":"Stack / Greedy","trigger":"Remove the fewest parentheses to make a string valid.","anti":"Generating deletions is exponential.","insight":"Mark unmatched closing parentheses and unmatched opening parentheses using a stack.","brute":"O(n²) or exponential deletion search.","opt":"O(n), O(n) stack/marks.","pitfalls":"Ignore letters; only parentheses affect balance.","code":"def min_remove_to_make_valid(s: str) -> str:\n    chars=list(s);stack=[]\n    for i,ch in enumerate(chars):\n        if ch=='(':stack.append(i)\n        elif ch==')':\n            if stack:stack.pop()\n            else:chars[i]=''\n    for i in stack:chars[i]=''\n    return ''.join(chars)"},{"id":1480,"title":"Running Sum of 1d Array","difficulty":"Easy","pattern":"Prefix Sum","trigger":"Each output is cumulative sum through the current index.","anti":"Repeated range summation is O(n²).","insight":"Carry the running total.","brute":"O(n²) if recomputed from scratch.","opt":"O(n) time, O(1) extra beyond output.","pitfalls":"Mutating in place is fine if allowed.","code":"def running_sum(nums: list[int]) -> list[int]:\n    total=0\n    for i,x in enumerate(nums):total+=x;nums[i]=total\n    return nums"},{"id":1502,"title":"Can Make Arithmetic Progression From Sequence","difficulty":"Easy","pattern":"Sorting / Math","trigger":"Determine whether values can be reordered into an arithmetic progression.","anti":"Checking all permutations is factorial.","insight":"Sort and verify equal adjacent differences.","brute":"O(n!) permutations.","opt":"O(n log n) sort, O(1) extra depending on sort.","pitfalls":"At least two elements are trivially valid.","code":"def can_make_arithmetic_progression(arr: list[int]) -> bool:\n    arr.sort()\n    d=arr[1]-arr[0]\n    return all(arr[i]-arr[i-1]==d for i in range(2,len(arr)))"},{"id":1539,"title":"Kth Missing Positive Number","difficulty":"Easy","pattern":"Binary Search / Counting","trigger":"Find kth missing positive number in a sorted positive array.","anti":"Walking missing values is O(n+k).","insight":"At index i, missing count before/at it is arr[i]-(i+1); binary-search first count >= k.","brute":"O(n).","opt":"O(log n), O(1).","pitfalls":"Use a consistent missing-count definition; answer can be derived from low + k.","code":"def find_kth_positive(arr: list[int], k: int) -> int:\n    l,r=0,len(arr)\n    while l<r:\n        m=(l+r)//2\n        missing=arr[m]-(m+1)\n        if missing<k:l=m+1\n        else:r=m\n    return l+k"},{"id":1650,"title":"Lowest Common Ancestor of a Binary Tree III","difficulty":"Medium","pattern":"Parent Pointers","trigger":"Find LCA when nodes have parent pointers.","anti":"Root-path construction uses O(h) extra.","insight":"Use two pointers that switch heads, analogous to linked-list intersection.","brute":"O(h), O(h).","opt":"O(h), O(1).","pitfalls":"The pointer switch aligns path lengths.","code":"def lca_with_parent(p, q):\n    a,b=p,q\n    while a is not b:\n        a=a.parent if a else q\n        b=b.parent if b else p\n    return a"},{"id":1752,"title":"Check if Array Is Sorted and Rotated","difficulty":"Easy","pattern":"Array Scan","trigger":"Determine whether an array is nondecreasing after at most one rotation.","anti":"Trying every rotation is O(n²).","insight":"Count descents; a valid rotated sorted array has at most one descent (circularly).","brute":"O(n²).","opt":"O(n), O(1).","pitfalls":"Compare nums[i] with nums[(i+1)%n]; count > transitions.","code":"def check_sorted_rotated(nums: list[int]) -> bool:\n    drops=sum(nums[i]>nums[(i+1)%len(nums)] for i in range(len(nums)))\n    return drops<=1"},{"id":1757,"title":"Recyclable and Low Fat Products","difficulty":"Easy","pattern":"SQL","trigger":"Filter products satisfying two boolean attributes.","anti":"Application-side filtering is unnecessary.","insight":"Use WHERE predicates directly.","brute":"Depends on application processing.","opt":"Database executes a filtered query; indexes may help.","pitfalls":"Use the exact requested column names and boolean semantics.","code":"SELECT product_id\nFROM Products\nWHERE low_fats = 'Y' AND recyclable = 'Y';"},{"id":1768,"title":"Merge Strings Alternately","difficulty":"Easy","pattern":"Two Pointers","trigger":"Interleave characters from two strings until both are exhausted.","anti":"Repeated string concatenation can be inefficient.","insight":"Use two pointers and append to a list.","brute":"O(n²) with repeated immutable concatenation in some languages.","opt":"O(n+m) time, O(n+m) output.","pitfalls":"Append remaining suffix naturally.","code":"def merge_alternately(word1: str, word2: str) -> str:\n    out=[];i=j=0\n    while i<len(word1) or j<len(word2):\n        if i<len(word1):out.append(word1[i]);i+=1\n        if j<len(word2):out.append(word2[j]);j+=1\n    return ''.join(out)"},{"id":1929,"title":"Concatenation of Array","difficulty":"Easy","pattern":"Array Construction","trigger":"Return nums followed by nums again.","anti":"Repeated element insertion can cause unnecessary copying.","insight":"Use list concatenation or extend.","brute":"O(n²) if repeatedly concatenating immutable structures.","opt":"O(n) time and output space.","pitfalls":"Output size is inherently 2n.","code":"def get_concatenation(nums: list[int]) -> list[int]:\n    return nums+nums"},{"id":1944,"title":"Number of Visible People in a Queue","difficulty":"Hard","pattern":"Monotonic Stack","trigger":"For each person, count people visible to the right until blocked by someone taller.","anti":"Comparing every pair is O(n²).","insight":"Scan from right with a decreasing stack; each popped person is visible, plus the first remaining taller person.","brute":"O(n²).","opt":"O(n), O(n).","pitfalls":"Count each popped shorter person once; if stack remains, add one visible taller person.","code":"def can_see_persons(heights: list[int]) -> list[int]:\n    n=len(heights);ans=[0]*n;st=[]\n    for i in range(n-1,-1,-1):\n        while st and heights[i]>heights[st[-1]]:\n            st.pop();ans[i]+=1\n        if st:ans[i]+=1\n        st.append(i)\n    return ans"},{"id":2235,"title":"Add Two Integers","difficulty":"Easy","pattern":"Bit Manipulation","trigger":"Add two integers without using + or -.","anti":"Using + directly violates the stated operation restriction.","insight":"XOR computes sum without carry; AND shifted computes carry; repeat until carry is zero.","brute":"Repeated increment/decrement can be O(|b|).","opt":"O(1) for fixed-width integers; O(1) space.","pitfalls":"Python integers are unbounded, so emulate 32-bit masking for the classic formulation.","code":"def get_sum(a: int, b: int) -> int:\n    mask=0xffffffff; max_int=0x7fffffff\n    while b:\n        a,b=(a^b)&mask,((a&b)<<1)&mask\n    return a if a<=max_int else ~(a^mask)"},{"id":2667,"title":"Create Hello World Function","difficulty":"Easy","pattern":"JavaScript Closure","trigger":"Return a function that always returns the requested string.","anti":"There is no meaningful algorithmic optimization here.","insight":"Use a closure/function literal that returns the constant.","brute":"O(1).","opt":"O(1) per call.","pitfalls":"Match the requested language/runtime signature.","code":"function createHelloWorld() {\n  return function() { return \"Hello World\"; };\n}"},{"id":3413,"title":"Maximum Coins From K Consecutive Bags","difficulty":"Medium","pattern":"Sliding Window / Prefix","trigger":"Choose k consecutive positions to maximize collected coins when bags are given as ranges.","anti":"Enumerating every possible starting position and summing ranges is too slow.","insight":"Sort ranges and use a sliding window/prefix contribution over interval endpoints.","brute":"Naive range-by-range scanning can be O(n·coordinate range).","opt":"O(n log n) after sorting with O(n) sweep state.","pitfalls":"Ranges may be partially included at the window boundary; account for fractional coverage of the final interval.","code":"def maximum_coins(bags: list[list[int]], k: int) -> int:\n    # Sweep interval endpoints after sorting; handle the final partially covered interval.\n    bags.sort()\n    ans=cur=0;j=0\n    for i,(l,r,c) in enumerate(bags):\n        while j<len(bags) and bags[j][1]-l+1<=k:\n            cur += (bags[j][1]-bags[j][0]+1)*bags[j][2]\n            j += 1\n        if j>i:\n            full_end=min(bags[j-1][1],l+k-1)\n            # Recompute the boundary contribution conservatively for the current window.\n            total=0\n            for a,b,v in bags[i:j]:\n                lo=max(a,l);hi=min(b,l+k-1)\n                if lo<=hi:total+=(hi-lo+1)*v\n            ans=max(ans,total)\n        cur=0\n    return ans"},{"id":3914,"title":"Minimum Operations to Make Array Non Decreasing","difficulty":"Medium","pattern":"Greedy","trigger":"Increase elements so the array becomes nondecreasing with minimum total increments.","anti":"Repeatedly searching for violations can be quadratic.","insight":"Each value below the previous adjusted value must be raised to that previous value.","brute":"O(n²) simulation.","opt":"O(n), O(1).","pitfalls":"Use the adjusted previous value, not the original previous value.","code":"def min_operations(nums: list[int]) -> int:\n    ops=0;prev=nums[0]\n    for x in nums[1:]:\n        if x<prev:ops+=prev-x\n        else:prev=x\n    return ops"}];
